{
  "name": "ID Photo Booth Pro",
  "description": "Ứng dụng chụp ảnh thẻ chuyên nghiệp (3x4, 4x6) với tính năng tách nền, thay trang phục và dàn trang in ấn.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum PhotoSize {
  SIZE_3X4 = '3x4',
  SIZE_4X6 = '4x6'
}

export enum BackgroundType {
  WHITE = 'white',
  BLUE = 'blue',
  ORIGINAL = 'original'
}

export enum AppStep {
  CAPTURE = 'capture',
  EDIT = 'edit',
  PRINT = 'print'
}

export interface PhotoSettings {
  size: PhotoSize;
  background: BackgroundType;
  brightness: number;
  contrast: number;
  smoothness: number; // Simulated beauty filter
  clothingPrompt?: string;
}

import { GoogleGenAI } from "@google/genai";
import { BackgroundType } from "../types";

const API_KEY = process.env.API_KEY || '';

// Initialize the client
const ai = new GoogleGenAI({ apiKey: API_KEY });

/**
 * Processes the image to remove background, change background color, 
 * or change clothes using Gemini's vision capabilities.
 */
export const processIDPhoto = async (
  imageBase64: string, 
  bgType: BackgroundType, 
  clothingPrompt: string | undefined
): Promise<string> => {
  if (!API_KEY) {
    throw new Error("API Key chưa được cấu hình.");
  }

  // Clean base64 string
  const cleanBase64 = imageBase64.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  let prompt = "Bạn là một chuyên gia chỉnh sửa ảnh thẻ ID chuyên nghiệp.";

  // Specific instructions for ID photos
  prompt += " Nhiệm vụ: Xử lý bức ảnh chân dung này để làm ảnh thẻ.";
  prompt += " QUAN TRỌNG: Giữ nguyên khuôn mặt, tóc và đầu của người trong ảnh để đảm bảo nhận diện (không được thay đổi facial features).";

  // Background logic
  if (bgType === BackgroundType.WHITE) {
    prompt += " Thay thế nền sau lưng người bằng màu trắng tinh khiết (Hex #FFFFFF).";
  } else if (bgType === BackgroundType.BLUE) {
    prompt += " Thay thế nền sau lưng người bằng màu xanh dương chuẩn ảnh thẻ (Hex #0057B7 hoặc màu xanh dương ID card tiêu chuẩn).";
  } else {
     prompt += " Giữ nguyên nền nhưng làm sạch nhiễu nếu có.";
  }

  // Clothing logic
  if (clothingPrompt) {
    prompt += ` Thay đổi trang phục của người đó thành: ${clothingPrompt}. Đảm bảo trang phục khớp với cổ và vai một cách tự nhiên.`;
  }

  prompt += " Ảnh trả về phải rõ nét, ánh sáng tốt, chuẩn hệ màu RGB.";

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image', // Using flash-image for good balance of speed and editing capability
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: cleanBase64
            }
          },
          {
            text: prompt
          }
        ]
      }
    });

    // Extract images from response parts
    const parts = response.candidates?.[0]?.content?.parts;
    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
          return `data:image/jpeg;base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("Không nhận được dữ liệu ảnh từ Gemini.");

  } catch (error) {
    console.error("Gemini processing error:", error);
    throw error;
  }
};

import React, { useRef, useState, useEffect } from 'react';
import { PhotoSize } from '../types';

interface CameraCaptureProps {
  onCapture: (imageSrc: string) => void;
  selectedSize: PhotoSize;
  onSizeChange: (size: PhotoSize) => void;
}

const CameraCapture: React.FC<CameraCaptureProps> = ({ onCapture, selectedSize, onSizeChange }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string>('');
  const [countdown, setCountdown] = useState<number | null>(null);

  useEffect(() => {
    startCamera();
    return () => {
      stopCamera();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const startCamera = async () => {
    try {
      const mediaStream = await navigator.mediaDevices.getUserMedia({
        video: {
          width: { ideal: 1920 },
          height: { ideal: 1080 },
          facingMode: "user"
        },
        audio: false
      });
      setStream(mediaStream);
      if (videoRef.current) {
        videoRef.current.srcObject = mediaStream;
      }
      setError('');
    } catch (err) {
      console.error(err);
      setError('Không thể truy cập camera. Vui lòng cấp quyền.');
    }
  };

  const stopCamera = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
    }
  };

  const handleCaptureClick = () => {
    setCountdown(3);
    const interval = setInterval(() => {
      setCountdown(prev => {
        if (prev === 1) {
          clearInterval(interval);
          captureFrame();
          return null;
        }
        return prev ? prev - 1 : null;
      });
    }, 1000);
  };

  const captureFrame = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      const context = canvas.getContext('2d');

      if (context) {
        // Set canvas dimensions to match video
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;

        // Draw standard frame
        context.translate(canvas.width, 0);
        context.scale(-1, 1); // Mirror effect correction for capture
        context.drawImage(video, 0, 0, canvas.width, canvas.height);

        // Reset transform
        context.setTransform(1, 0, 0, 1, 0, 0);

        const dataUrl = canvas.toDataURL('image/jpeg', 0.95);
        onCapture(dataUrl);
      }
    }
  };

  // Aspect ratio for the guide overlay
  // 3x4 = 0.75, 4x6 = 0.66
  const aspectRatio = selectedSize === PhotoSize.SIZE_3X4 ? 3/4 : 4/6;

  return (
    <div className="flex flex-col items-center justify-center h-full w-full bg-black relative">
      {error && (
        <div className="absolute z-50 bg-red-500 text-white p-4 rounded-lg">
          {error}
        </div>
      )}

      {/* Camera Feed Container */}
      <div className="relative w-full max-w-2xl aspect-[3/4] overflow-hidden bg-gray-900 rounded-lg shadow-2xl">
        <video
          ref={videoRef}
          autoPlay
          playsInline
          className="absolute inset-0 w-full h-full object-cover transform -scale-x-100" // Mirror for preview
        />

        {/* Guide Overlay */}
        <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
           <div 
             className="border-2 border-white/50 border-dashed rounded-full"
             style={{
               width: `${35 * 100 / aspectRatio}%`, // Approximate head guide
               height: '35%',
               transform: 'translateY(-10%)'
             }}
           ></div>
           <div 
             className="border-2 border-brand-500 shadow-[0_0_20px_rgba(59,130,246,0.5)] z-10"
             style={{
               width: 'auto',
               height: '80%',
               aspectRatio: `${aspectRatio}`,
             }}
           ></div>
        </div>

        {countdown !== null && (
          <div className="absolute inset-0 flex items-center justify-center bg-black/40 z-20">
            <span className="text-9xl font-bold text-white animate-bounce">{countdown}</span>
          </div>
        )}
      </div>

      {/* Controls */}
      <div className="w-full max-w-2xl mt-6 flex flex-col items-center gap-4 px-4">

        {/* Size Selection */}
        <div className="flex bg-gray-800 rounded-full p-1 gap-1">
          <button
            onClick={() => onSizeChange(PhotoSize.SIZE_3X4)}
            className={`px-6 py-2 rounded-full text-sm font-medium transition-all ${
              selectedSize === PhotoSize.SIZE_3X4 
                ? 'bg-brand-600 text-white shadow-lg' 
                : 'text-gray-400 hover:text-white'
            }`}
          >
            3x4 cm
          </button>
          <button
            onClick={() => onSizeChange(PhotoSize.SIZE_4X6)}
            className={`px-6 py-2 rounded-full text-sm font-medium transition-all ${
              selectedSize === PhotoSize.SIZE_4X6 
                ? 'bg-brand-600 text-white shadow-lg' 
                : 'text-gray-400 hover:text-white'
            }`}
          >
            4x6 cm
          </button>
        </div>

        {/* Capture Button */}
        <button
          onClick={handleCaptureClick}
          disabled={countdown !== null}
          className="w-20 h-20 rounded-full bg-white border-8 border-gray-300 hover:border-gray-400 hover:bg-gray-100 transition-all focus:outline-none focus:ring-4 focus:ring-brand-500/50 shadow-lg"
          aria-label="Chụp ảnh"
        ></button>
      </div>

      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

export default CameraCapture;

import React, { useState, useEffect } from 'react';
import { BackgroundType, PhotoSettings, PhotoSize } from '../types';
import { processIDPhoto } from '../services/geminiService';

interface ImageEditorProps {
  originalImage: string;
  settings: PhotoSettings;
  onUpdateSettings: (newSettings: PhotoSettings) => void;
  onProcessedImage: (img: string) => void; // Pass back the final processed image base64
  onNext: () => void;
  onRetake: () => void;
}

const ImageEditor: React.FC<ImageEditorProps> = ({ 
  originalImage, 
  settings, 
  onUpdateSettings,
  onProcessedImage,
  onNext,
  onRetake
}) => {
  const [displayImage, setDisplayImage] = useState<string>(originalImage);
  const [isProcessing, setIsProcessing] = useState(false);
  const [clothingInput, setClothingInput] = useState('');
  const [apiError, setApiError] = useState('');

  // Apply visual CSS filters instantly
  const filterStyle = {
    filter: `brightness(${settings.brightness}%) contrast(${settings.contrast}%) saturate(110%) blur(${settings.smoothness}px)`,
  };

  // Helper to handle AI processing requests
  const handleAIProcessing = async (targetBg: BackgroundType, targetClothing?: string) => {
    setIsProcessing(true);
    setApiError('');
    try {
      // If we are just reverting to original bg and no clothes change, revert to captured
      if (targetBg === BackgroundType.ORIGINAL && !targetClothing) {
        setDisplayImage(originalImage);
        onUpdateSettings({ ...settings, background: targetBg, clothingPrompt: undefined });
      } else {
        // Call Gemini
        const result = await processIDPhoto(originalImage, targetBg, targetClothing);
        setDisplayImage(result);
        onUpdateSettings({ ...settings, background: targetBg, clothingPrompt: targetClothing });
      }
    } catch (err: any) {
      setApiError(err.message || "Có lỗi xảy ra khi xử lý ảnh.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleClothingSubmit = () => {
    if (!clothingInput.trim()) return;
    handleAIProcessing(settings.background, clothingInput);
  };

  // When clicking Next, we need to apply the CSS filters permanently to a canvas and pass that forward
  const handleFinish = () => {
    const canvas = document.createElement('canvas');
    const img = new Image();
    img.src = displayImage;
    img.onload = () => {
      // Create a canvas with the target ratio
      const aspectRatio = settings.size === PhotoSize.SIZE_3X4 ? 3/4 : 4/6;

      // Calculate crop to fit ratio centered
      let sourceW = img.width;
      let sourceH = img.height;
      let targetW, targetH;
      let offsetX = 0;
      let offsetY = 0;

      if (sourceW / sourceH > aspectRatio) {
        // Image is wider than needed
        targetH = sourceH;
        targetW = sourceH * aspectRatio;
        offsetX = (sourceW - targetW) / 2;
      } else {
        // Image is taller than needed
        targetW = sourceW;
        targetH = sourceW / aspectRatio;
        offsetY = (sourceH - targetH) / 2;
      }

      // High res output
      canvas.width = targetW;
      canvas.height = targetH;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        // Apply filters
        ctx.filter = `brightness(${settings.brightness}%) contrast(${settings.contrast}%) saturate(110%) blur(${settings.smoothness}px)`;

        ctx.drawImage(
          img, 
          offsetX, offsetY, targetW, targetH, // Source
          0, 0, targetW, targetH // Dest
        );

        onProcessedImage(canvas.toDataURL('image/png'));
        onNext();
      }
    };
  };

  return (
    <div className="flex flex-col md:flex-row h-full w-full bg-gray-50 overflow-hidden">

      {/* Sidebar Controls */}
      <div className="w-full md:w-96 bg-white shadow-lg p-6 flex flex-col gap-6 overflow-y-auto z-10 border-r border-gray-200">

        <div>
          <h2 className="text-xl font-bold text-gray-800 mb-4 flex items-center gap-2">
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4m6 6v10m6-2a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4"></path></svg>
            Chỉnh sửa
          </h2>

          {/* Background Selection */}
          <div className="mb-6">
            <label className="block text-sm font-medium text-gray-700 mb-2">Màu nền</label>
            <div className="grid grid-cols-3 gap-2">
              <button 
                onClick={() => handleAIProcessing(BackgroundType.ORIGINAL, settings.clothingPrompt)}
                className={`h-10 rounded border flex items-center justify-center text-xs ${settings.background === BackgroundType.ORIGINAL ? 'ring-2 ring-brand-500 border-transparent' : 'border-gray-300'}`}
              >
                Gốc
              </button>
              <button 
                onClick={() => handleAIProcessing(BackgroundType.WHITE, settings.clothingPrompt)}
                className={`h-10 rounded border flex items-center justify-center text-xs bg-white ${settings.background === BackgroundType.WHITE ? 'ring-2 ring-brand-500 border-gray-200' : 'border-gray-300'}`}
              >
                Trắng
              </button>
              <button 
                onClick={() => handleAIProcessing(BackgroundType.BLUE, settings.clothingPrompt)}
                className={`h-10 rounded border flex items-center justify-center text-xs bg-[#0057B7] text-white ${settings.background === BackgroundType.BLUE ? 'ring-2 ring-brand-500 border-transparent' : 'border-gray-300'}`}
              >
                Xanh
              </button>
            </div>
            <p className="text-xs text-gray-500 mt-1">*Sử dụng AI để tách nền</p>
          </div>

          {/* Sliders */}
          <div className="space-y-4 mb-6">
            <div>
              <label className="flex justify-between text-sm font-medium text-gray-700">
                Làm sáng da
                <span className="text-gray-400">{settings.brightness}%</span>
              </label>
              <input 
                type="range" min="80" max="150" 
                value={settings.brightness}
                onChange={(e) => onUpdateSettings({...settings, brightness: Number(e.target.value)})}
                className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-brand-600"
              />
            </div>
            <div>
              <label className="flex justify-between text-sm font-medium text-gray-700">
                Độ tương phản
                <span className="text-gray-400">{settings.contrast}%</span>
              </label>
              <input 
                type="range" min="80" max="150" 
                value={settings.contrast}
                onChange={(e) => onUpdateSettings({...settings, contrast: Number(e.target.value)})}
                className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-brand-600"
              />
            </div>
            <div>
              <label className="flex justify-between text-sm font-medium text-gray-700">
                Làm mịn (Beauty)
                <span className="text-gray-400">{settings.smoothness}</span>
              </label>
              <input 
                type="range" min="0" max="3" step="0.1"
                value={settings.smoothness}
                onChange={(e) => onUpdateSettings({...settings, smoothness: Number(e.target.value)})}
                className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-brand-600"
              />
            </div>
          </div>

          {/* Clothes Changer */}
          <div className="mb-6 p-4 bg-blue-50 rounded-lg border border-blue-100">
            <label className="block text-sm font-bold text-blue-800 mb-2">Thay trang phục (AI)</label>
            <div className="flex gap-2 mb-2">
              <input 
                type="text"
                placeholder="VD: Vest đen, sơ mi trắng..."
                value={clothingInput}
                onChange={(e) => setClothingInput(e.target.value)}
                className="flex-1 rounded border-gray-300 text-sm p-2 focus:ring-blue-500 focus:border-blue-500"
              />
            </div>
            <button 
              onClick={handleClothingSubmit}
              disabled={isProcessing || !clothingInput}
              className="w-full py-2 bg-blue-600 text-white rounded text-sm font-medium hover:bg-blue-700 disabled:opacity-50 transition"
            >
              {isProcessing ? 'Đang xử lý...' : 'Thực hiện'}
            </button>
            <p className="text-xs text-blue-600 mt-2 italic">Lưu ý: AI sẽ tạo lại phần thân áo.</p>
          </div>

          {apiError && (
             <div className="p-3 bg-red-100 text-red-700 text-sm rounded mb-4">
               {apiError}
             </div>
          )}

        </div>

        <div className="mt-auto flex flex-col gap-3">
          <button 
            onClick={handleFinish}
            className="w-full py-3 bg-brand-600 text-white rounded-lg font-bold shadow hover:bg-brand-700 transition"
          >
            Tiếp tục & In ấn
          </button>
          <button 
            onClick={onRetake}
            className="w-full py-3 bg-white text-gray-600 border border-gray-300 rounded-lg font-medium hover:bg-gray-50 transition"
          >
            Chụp lại
          </button>
        </div>
      </div>

      {/* Main Preview Area */}
      <div className="flex-1 bg-gray-100 flex items-center justify-center p-8 relative">
        <div className="relative shadow-2xl rounded-sm overflow-hidden bg-white border-8 border-white">

          {isProcessing && (
            <div className="absolute inset-0 bg-white/80 z-20 flex flex-col items-center justify-center">
              <div className="animate-spin rounded-full h-12 w-12 border-4 border-brand-500 border-t-transparent"></div>
              <p className="mt-4 text-brand-700 font-medium">Đang xử lý AI...</p>
            </div>
          )}

          <img 
            src={displayImage} 
            alt="Preview" 
            style={{
               ...filterStyle,
               maxHeight: '70vh',
               maxWidth: '100%',
               objectFit: 'contain'
            }}
          />

          {/* Crop Overlay Guide (Visual only) */}
          <div className="absolute inset-0 border-2 border-dashed border-red-400/50 pointer-events-none"></div>
          <div className="absolute top-2 left-2 bg-black/50 text-white text-xs px-2 py-1 rounded">
            Hệ màu: RGB
          </div>
          <div className="absolute top-2 right-2 bg-brand-600 text-white text-xs px-2 py-1 rounded">
            Khổ: {settings.size === PhotoSize.SIZE_3X4 ? '3x4 cm' : '4x6 cm'}
          </div>
        </div>
      </div>
    </div>
  );
};

export default ImageEditor;

import React, { useRef } from 'react';
import { PhotoSize } from '../types';

interface PrintPreviewProps {
  processedImage: string;
  size: PhotoSize;
  onBack: () => void;
  onNew: () => void;
}

const PrintPreview: React.FC<PrintPreviewProps> = ({ processedImage, size, onBack, onNew }) => {
  const printRef = useRef<HTMLDivElement>(null);

  // 13cm x 18cm paper
  // For screen display we assume 1cm approx 37.8px (96dpi) but we use relative sizing for responsiveness
  // or precise mm for print css.

  // Logic: 
  // 13cm width. 3cm photo fits 4 times (12cm). Gap 1cm/5 = 0.2cm.
  // 18cm height. 4cm photo fits 4 times (16cm). Gap 2cm/5 = 0.4cm.

  // Grid config
  const is3x4 = size === PhotoSize.SIZE_3X4;

  const handlePrint = () => {
    window.print();
  };

  const handleDownload = () => {
    const link = document.createElement('a');
    link.href = processedImage;
    link.download = `ID-Photo-${size}-${Date.now()}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleZaloShare = () => {
    // Client-side simulation
    handleDownload();
    alert("Ảnh đã được lưu về máy!\n\nVui lòng mở Zalo và gửi ảnh vừa tải về cho người nhận.\n(Tính năng gửi trực tiếp cần tích hợp Server doanh nghiệp Zalo OA)");
    // Alternatively generate a deep link if possible, but usually restricted.
    window.open('https://zalo.me/', '_blank');
  };

  return (
    <div className="flex flex-col h-full bg-gray-100">

      {/* Header */}
      <header className="bg-white shadow-sm p-4 flex justify-between items-center no-print">
        <h1 className="text-xl font-bold text-gray-800">Xem trước bản in</h1>
        <div className="flex gap-2">
          <button onClick={onBack} className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded">
            Chỉnh sửa lại
          </button>
          <button onClick={onNew} className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded">
            Khách mới
          </button>
        </div>
      </header>

      <div className="flex-1 overflow-auto p-8 flex justify-center items-start gap-8">

        {/* Print Canvas Container */}
        {/* CSS defines 130mm x 180mm for print. On screen we scale it up. */}
        <div className="bg-white shadow-2xl p-0 overflow-hidden relative" style={{ width: '130mm', height: '180mm', minWidth: '130mm', minHeight: '180mm' }}>

            {/* Grid Layout */}
            <div className="w-full h-full p-[5mm] flex flex-wrap content-start gap-[2mm]">
              {/* Generate standard grid based on size */}
              {Array.from({ length: is3x4 ? 16 : 8 }).map((_, i) => (
                <div 
                  key={i} 
                  className="overflow-hidden border border-gray-100"
                  style={{
                    width: is3x4 ? '28mm' : '38mm', // slightly less than 30mm/40mm to account for gaps/margins
                    height: is3x4 ? '38mm' : '58mm',
                  }}
                >
                  <img 
                    src={processedImage} 
                    className="w-full h-full object-cover" 
                    alt="ID Photo"
                  />
                </div>
              ))}
            </div>

            {/* Print Marks / Footer */}
            <div className="absolute bottom-2 right-2 text-[10px] text-gray-300">
               ID Photo Booth Pro - {new Date().toLocaleDateString()}
            </div>
        </div>

        {/* Action Panel */}
        <div className="w-80 bg-white p-6 rounded-xl shadow-lg flex flex-col gap-4 no-print sticky top-8">
          <h3 className="font-bold text-lg text-gray-800">Hoàn tất</h3>

          <div className="bg-blue-50 p-4 rounded-lg">
            <p className="text-sm text-blue-800 mb-1">Thông số in:</p>
            <ul className="text-sm text-blue-700 list-disc list-inside">
              <li>Khổ giấy: <b>13x18 cm</b></li>
              <li>Kích thước ảnh: <b>{size}</b></li>
              <li>Số lượng: <b>{is3x4 ? '16' : '8'} ảnh</b></li>
            </ul>
          </div>

