import React, { useState } from 'react';
import CameraCapture from './components/CameraCapture';
import ImageEditor from './components/ImageEditor';
import PrintPreview from './components/PrintPreview';
import { AppStep, BackgroundType, PhotoSettings, PhotoSize } from './types';

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.CAPTURE);

  // Data State
  const [capturedImage, setCapturedImage] = useState<string>('');
  const [processedImage, setProcessedImage] = useState<string>('');

  // Settings State
  const [settings, setSettings] = useState<PhotoSettings>({
    size: PhotoSize.SIZE_3X4,
    background: BackgroundType.ORIGINAL,
    brightness: 100,
    contrast: 100,
    smoothness: 0,
    clothingPrompt: undefined
  });

  const handleCapture = (imageSrc: string) => {
    setCapturedImage(imageSrc);
    setStep(AppStep.EDIT);
  };

  const handleProcessedImage = (img: string) => {
    setProcessedImage(img);
  };

  const resetApp = () => {
    setCapturedImage('');
    setProcessedImage('');
    setSettings({
      size: PhotoSize.SIZE_3X4,
      background: BackgroundType.ORIGINAL,
      brightness: 100,
      contrast: 100,
      smoothness: 0,
      clothingPrompt: undefined
    });
    setStep(AppStep.CAPTURE);
  };

  return (
    <div className="h-full w-full font-sans">
