/**
 * DATABASE SERVICE (GOOGLE CLOUD / FIREBASE)
 * 
 * Lưu ý: Trong môi trường demo frontend này, chúng ta không thể lưu trực tiếp API Key
 * có quyền ghi (write permission) vào Google Cloud Firestore vì lý do bảo mật.
 * 
 * Service này được thiết kế để:
 * 1. Chạy ngay lập tức bằng cách sử dụng LocalStorage (giả lập DB).
 * 2. Dễ dàng chuyển đổi sang Firebase Firestore bằng cách uncomment đoạn code bên dưới.
 */

// --- CẤU HÌNH FIREBASE (KHI TRIỂN KHAI THỰC TẾ) ---
/*
import { initializeApp } from "firebase/app";
import { getFirestore, collection, addDoc, getDocs, orderBy, query } from "firebase/firestore";

const firebaseConfig = {
  apiKey: "YOUR_API_KEY",
  authDomain: "YOUR_PROJECT.firebaseapp.com",
  projectId: "YOUR_PROJECT_ID",
