*/

const DB_KEY = 'id_photo_booth_db';

export const savePhotoToCloud = async (photo: SavedPhoto): Promise<boolean> => {
  try {
    // --- CODE CHO GOOGLE FIRESTORE ---
    /*
    await addDoc(collection(db, "photos"), {
      ...photo,
      timestamp: new Date().toISOString()
    });
    return true;
    */

    // --- CODE GIẢ LẬP (LOCAL STORAGE) ---
    const currentData = localStorage.getItem(DB_KEY);
    const photos: SavedPhoto[] = currentData ? JSON.parse(currentData) : [];
    photos.unshift(photo); // Add to beginning
    localStorage.setItem(DB_KEY, JSON.stringify(photos));

    // Giả lập độ trễ mạng
    await new Promise(resolve => setTimeout(resolve, 500));
    return true;
  } catch (error) {
    console.error("Error saving to DB:", error);
    return false;
  }
};

export const getPhotosFromCloud = async (): Promise<SavedPhoto[]> => {
  try {
    // --- CODE CHO GOOGLE FIRESTORE ---
    /*
    const q = query(collection(db, "photos"), orderBy("timestamp", "desc"));
    const querySnapshot = await getDocs(q);
    return querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as SavedPhoto));
    */

    // --- CODE GIẢ LẬP (LOCAL STORAGE) ---
    const currentData = localStorage.getItem(DB_KEY);
    await new Promise(resolve => setTimeout(resolve, 300));
    return currentData ? JSON.parse(currentData) : [];
  } catch (error) {
    console.error("Error fetching from DB:", error);
    return [];
  }
};

export const deletePhotoFromCloud = async (id: string): Promise<boolean> => {
  try {
    const currentData = localStorage.getItem(DB_KEY);
    if (!currentData) return false;

    let photos: SavedPhoto[] = JSON.parse(currentData);
    photos = photos.filter(p => p.id !== id);
    localStorage.setItem(DB_KEY, JSON.stringify(photos));
    return true;
  } catch (error) {
    return false;
  }
};

