import React, { useRef, useState, useEffect } from 'react';
import { PhotoSize } from '../types';

interface CameraCaptureProps {
  onCapture: (imageSrc: string) => void;
  selectedSize: PhotoSize;
  onSizeChange: (size: PhotoSize) => void;
}

const CameraCapture: React.FC<CameraCaptureProps> = ({ onCapture, selectedSize, onSizeChange }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string>('');
  const [countdown, setCountdown] = useState<number | null>(null);

  // Device management
  const [devices, setDevices] = useState<MediaDeviceInfo[]>([]);
  const [selectedDeviceId, setSelectedDeviceId] = useState<string>('');

  useEffect(() => {
    getDevices();
    // Start with default camera
    startCamera();

    return () => {
      stopCamera();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // When device selection changes
  useEffect(() => {
    if (selectedDeviceId) {
      startCamera(selectedDeviceId);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedDeviceId]);

  const getDevices = async () => {
    try {
      const allDevices = await navigator.mediaDevices.enumerateDevices();
      const videoDevices = allDevices.filter(device => device.kind === 'videoinput');
      setDevices(videoDevices);

      // Try to find Canon if available
      const canon = videoDevices.find(d => d.label.toLowerCase().includes('canon') || d.label.toLowerCase().includes('eos'));
      if (canon) {
        setSelectedDeviceId(canon.deviceId);
      }
    } catch (err) {
      console.error("Error enumerating devices", err);
    }
  };

  const startCamera = async (deviceId?: string) => {
    stopCamera();
    try {
      const constraints: MediaStreamConstraints = {
        video: {
          deviceId: deviceId ? { exact: deviceId } : undefined,
          width: { ideal: 1920 }, // Full HD for better quality
          height: { ideal: 1080 },
        },
        audio: false
      };

      const mediaStream = await navigator.mediaDevices.getUserMedia(constraints);
      setStream(mediaStream);
      if (videoRef.current) {
        videoRef.current.srcObject = mediaStream;
      }
      setError('');
    } catch (err) {
      console.error(err);
      setError('Không thể truy cập camera. Hãy đảm bảo Canon 1100D đã kết nối (EOS Webcam Utility) hoặc Webcam đang hoạt động.');
    }
  };

  const stopCamera = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
    }
  };

  const handleCaptureClick = () => {
    setCountdown(3);
    const interval = setInterval(() => {
      setCountdown(prev => {
        if (prev === 1) {
          clearInterval(interval);
          captureFrame();
          return null;
        }
        return prev ? prev - 1 : null;
      });
    }, 1000);
  };

  const captureFrame = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      const context = canvas.getContext('2d');

      if (context) {
        // Set canvas dimensions to match video
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;

        // Draw standard frame
        // Note: If using a real camera (Canon) via Webcam Utility, it might NOT be mirrored.
        // If it looks mirrored in preview, we mirror it back. Assuming user wants WYSIWYG.
        // For self-capture (webcam), mirror is good. For DSLR operator, normal is better.
        // Here we keep mirror logic for consistency with UI preview.

        context.translate(canvas.width, 0);
        context.scale(-1, 1); 
        context.drawImage(video, 0, 0, canvas.width, canvas.height);

        context.setTransform(1, 0, 0, 1, 0, 0);

        const dataUrl = canvas.toDataURL('image/jpeg', 1.0); // Max quality
        onCapture(dataUrl);
      }
    }
  };

  // Guide Ratios
  const is3x4 = selectedSize === PhotoSize.SIZE_3X4;

  // Calculate aspect ratio for the frame container
  // However, the video feed is likely 16:9. We need to overlay the 3x4 or 4x6 crop box on top.
  const targetRatio = is3x4 ? 3/4 : 4/6;

  return (
    <div className="flex flex-col items-center justify-center h-full w-full bg-gray-900 relative">

      {/* Top Bar: Device Selection */}
      <div className="absolute top-4 left-4 z-50 bg-black/50 p-2 rounded-lg backdrop-blur-sm">
        <label className="text-xs text-gray-300 block mb-1">Thiết bị đầu vào (Canon/Webcam):</label>
        <select 
          value={selectedDeviceId}
          onChange={(e) => setSelectedDeviceId(e.target.value)}
          className="bg-gray-800 text-white text-sm border border-gray-600 rounded px-2 py-1 outline-none focus:border-brand-500"
        >
          <option value="">-- Chọn Camera --</option>
          {devices.map((device, index) => (
            <option key={device.deviceId || index} value={device.deviceId}>
              {device.label || `Camera ${index + 1}`}
            </option>
          ))}
        </select>
      </div>

      {error && (
        <div className="absolute z-50 bg-red-500 text-white p-4 rounded-lg shadow-xl">
          {error}
        </div>
      )}

      {/* Camera Feed Container */}
      <div className="relative h-[80vh] aspect-[3/4] overflow-hidden bg-black rounded-sm shadow-2xl border border-gray-700">
        <video
          ref={videoRef}
          autoPlay
          playsInline
          className="absolute inset-0 w-full h-full object-cover transform -scale-x-100" 
        />

        {/* PROFESSIONAL GUIDE OVERLAY (Quy chuẩn quốc gia) */}
        <div className="absolute inset-0 pointer-events-none flex items-center justify-center">

           {/* The Safe Area Box (Actual Crop Area) */}
           <div 
             className="relative border-2 border-brand-400/80 shadow-[0_0_0_9999px_rgba(0,0,0,0.7)]"
             style={{
               height: '90%',
               aspectRatio: `${targetRatio}`,
             }}
           >
              {/* Silhouette Guide SVG */}
              <svg viewBox="0 0 100 100" className="absolute inset-0 w-full h-full opacity-60">
                {/* Center Line */}
                <line x1="50" y1="0" x2="50" y2="100" stroke="white" strokeWidth="0.5" strokeDasharray="2,2" />

                {/* Eye Line (approx 45-50% from bottom for full head shot, or 60% from bottom typically) */}
                {/* Standard ID: Eyes are at ~60% height from bottom */}
                <line x1="20" y1="45" x2="80" y2="45" stroke="#3b82f6" strokeWidth="0.5" />
                <text x="82" y="46" fill="#3b82f6" fontSize="3">Mắt</text>

                {/* Head Top Margin (Head should be ~70-80% of photo) */}
                <line x1="35" y1="12" x2="65" y2="12" stroke="red" strokeWidth="0.5" />
                <text x="67" y="13" fill="red" fontSize="3">Đỉnh đầu</text>

                {/* Chin Line */}
                <line x1="40" y1="78" x2="60" y2="78" stroke="red" strokeWidth="0.5" />
                <text x="62" y="79" fill="red" fontSize="3">Cằm</text>

                {/* Face Oval Guide */}
                <ellipse cx="50" cy="45" rx="22" ry="33" fill="none" stroke="white" strokeWidth="1" strokeDasharray="4,2" />

                {/* Shoulder Curve */}
                <path d="M 10 100 Q 25 85 50 85 Q 75 85 90 100" fill="none" stroke="white" strokeWidth="1" strokeDasharray="4,2" />
              </svg>

              <div className="absolute bottom-2 left-0 right-0 text-center text-white/70 text-xs font-mono">
                {is3x4 ? 'KHUNG 3x4' : 'KHUNG 4x6'}
              </div>
           </div>
        </div>

        {countdown !== null && (
          <div className="absolute inset-0 flex items-center justify-center bg-black/40 z-20">
            <span className="text-9xl font-bold text-white animate-bounce">{countdown}</span>
          </div>
        )}
      </div>

      {/* Controls */}
      <div className="absolute bottom-8 left-0 right-0 flex justify-center items-center gap-8">

        {/* Size Selection */}
        <div className="flex bg-gray-800/80 backdrop-blur rounded-full p-1 gap-1 border border-gray-600">
          <button
            onClick={() => onSizeChange(PhotoSize.SIZE_3X4)}
            className={`px-6 py-3 rounded-full text-sm font-bold transition-all ${
              selectedSize === PhotoSize.SIZE_3X4 
                ? 'bg-brand-600 text-white shadow-lg' 
                : 'text-gray-400 hover:text-white'
            }`}
          >
            3x4 cm
          </button>
          <button
            onClick={() => onSizeChange(PhotoSize.SIZE_4X6)}
            className={`px-6 py-3 rounded-full text-sm font-bold transition-all ${
              selectedSize === PhotoSize.SIZE_4X6 
                ? 'bg-brand-600 text-white shadow-lg' 
                : 'text-gray-400 hover:text-white'
            }`}
          >
            4x6 cm
          </button>
        </div>

        {/* Capture Button */}
        <button
          onClick={handleCaptureClick}
          disabled={countdown !== null}
          className="w-20 h-20 rounded-full bg-white border-8 border-gray-300 hover:border-brand-400 hover:scale-105 active:scale-95 transition-all focus:outline-none shadow-[0_0_20px_rgba(0,0,0,0.5)]"
          aria-label="Chụp ảnh"
        >
           <div className="w-full h-full rounded-full bg-white border-4 border-black/10"></div>
        </button>

        {/* Placeholder for symmetry */}
        <div className="w-[180px]"></div>
      </div>

      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

export default CameraCapture;

import React, { useState } from 'react';
import { PhotoSettings, PhotoSize } from '../types';
import { savePhotoToCloud } from '../services/databaseService';

interface PrintPreviewProps {
  processedImage: string;
  size: PhotoSize;
  settings: PhotoSettings;
  onBack: () => void;
  onNew: () => void;
  onSaved?: () => void;
}

const PrintPreview: React.FC<PrintPreviewProps> = ({ 
  processedImage, 
  size, 
  settings, 
  onBack, 
  onNew,
  onSaved 
}) => {
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  // Grid config
  const is3x4 = size === PhotoSize.SIZE_3X4;

  const handlePrint = () => {
    window.print();
  };

  const handleDownload = () => {
    const link = document.createElement('a');
    link.href = processedImage;
    link.download = `ID-Photo-${size}-${Date.now()}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleSaveToDB = async () => {
    setIsSaving(true);
    const success = await savePhotoToCloud({
      id: Date.now().toString(),
      dataUrl: processedImage,
      timestamp: Date.now(),
      settings: settings
    });

    setIsSaving(false);
    if (success) {
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
      if (onSaved) onSaved();
    } else {
      alert("Lỗi khi lưu vào cơ sở dữ liệu");
    }
  };

  const handleZaloShare = () => {
    handleDownload();
    alert("Ảnh đã được lưu về máy!\n\nVui lòng mở Zalo và gửi ảnh vừa tải về cho người nhận.\n(Tính năng gửi trực tiếp cần tích hợp Server doanh nghiệp Zalo OA)");
    window.open('https://zalo.me/', '_blank');
  };

  return (
    <div className="flex flex-col h-full bg-gray-100">

      {/* Header */}
      <header className="bg-white shadow-sm p-4 flex justify-between items-center no-print">
        <h1 className="text-xl font-bold text-gray-800">Xem trước bản in (Epson L8050)</h1>
        <div className="flex gap-2">
          <button onClick={onBack} className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded">
            Chỉnh sửa lại
          </button>
          <button onClick={onNew} className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded">
            Khách mới
          </button>
        </div>
      </header>

      <div className="flex-1 overflow-auto p-8 flex justify-center items-start gap-8">

        {/* Print Canvas Container */}
        {/* 
           Epson L8050 Paper Size: 13x18cm (5x7 inches)
           CSS Size: 130mm x 180mm
           Background must be white.
        */}
        <div 
          className="bg-white shadow-2xl overflow-hidden relative print:shadow-none" 
          style={{ 
            width: '130mm', 
            height: '180mm', 
            minWidth: '130mm', 
            minHeight: '180mm',
            border: '1px solid #e5e7eb'
          }}
        >

            {/* Grid Layout */}
            <div className="w-full h-full p-[5mm] flex flex-wrap content-start gap-[2mm]">
              {/* Generate standard grid based on size */}
              {Array.from({ length: is3x4 ? 16 : 8 }).map((_, i) => (
                <div 
                  key={i} 
                  className="overflow-hidden border border-gray-200"
                  style={{
                    width: is3x4 ? '27mm' : '37mm', // Tinh chỉnh nhỏ hơn 1 chút để lọt lòng grid
                    height: is3x4 ? '37mm' : '57mm',
                  }}
                >
                  <img 
                    src={processedImage} 
                    className="w-full h-full object-cover" 
                    alt="ID Photo"
                  />
                </div>
              ))}
            </div>

            {/* Print Marks / Footer - Hidden on actual photo paper usually, but good for reference */}
            <div className="absolute bottom-1 right-2 text-[8px] text-gray-300 print:text-gray-100">
               Epson L8050 - Photo Mode
            </div>
        </div>

        {/* Action Panel */}
        <div className="w-80 bg-white p-6 rounded-xl shadow-lg flex flex-col gap-4 no-print sticky top-8">
          <h3 className="font-bold text-lg text-gray-800">Chuẩn bị in</h3>

          <div className="bg-yellow-50 p-4 rounded-lg border border-yellow-100">
            <p className="text-sm font-bold text-yellow-800 mb-2 flex items-center gap-1">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
              Lưu ý thiết lập máy in Epson:
            </p>
            <ul className="text-xs text-yellow-800 list-disc list-inside space-y-1">
              <li>Paper Size: <b>13x18 cm (5x7 in)</b></li>
              <li>Paper Type: <b>Epson Premium Glossy</b></li>
              <li>Quality: <b>High / Best</b></li>
              <li>Scale: <b>100% (Không Scale)</b></li>
            </ul>
          </div>

          <div className="bg-blue-50 p-4 rounded-lg">
             <div className="flex justify-between items-center mb-1">
               <span className="text-sm text-blue-800">Loại ảnh:</span>
               <span className="text-sm font-bold text-blue-800">{settings.size}</span>
             </div>
             <div className="flex justify-between items-center">
               <span className="text-sm text-blue-800">Số lượng:</span>
               <span className="text-sm font-bold text-blue-800">{is3x4 ? '16' : '8'} ảnh</span>
             </div>
          </div>

          <button 
            onClick={handlePrint}
            className="flex items-center justify-center gap-2 w-full py-3 bg-gray-900 hover:bg-black text-white rounded-lg font-bold transition shadow-md"
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z"></path></svg>
            In Ngay (Ctrl+P)
          </button>

          <button 
            onClick={handleSaveToDB}
            disabled={isSaving || saveSuccess}
            className={`flex items-center justify-center gap-2 w-full py-3 rounded-lg font-bold transition ${saveSuccess ? 'bg-green-600 text-white' : 'bg-brand-600 hover:bg-brand-700 text-white'}`}
          >
            {isSaving ? (
              'Đang lưu...'
            ) : saveSuccess ? (
              <>Đã lưu vào DB</>
            ) : (
              <>Lưu vào CSDL</>
            )}
          </button>

          <hr className="border-gray-100" />

          <button 
            onClick={handleZaloShare}
            className="flex items-center justify-center gap-2 w-full py-3 bg-blue-500 hover:bg-blue-600 text-white rounded-lg font-bold transition"
          >
            Gửi Zalo
          </button>
        </div>

      </div>
    </div>
  );
};

export default PrintPreview;

