import React, { useRef, useState, useEffect } from 'react';
import { PhotoSize } from '../types';

interface CameraCaptureProps {
  onCapture: (imageSrc: string) => void;
  selectedSize: PhotoSize;
  onSizeChange: (size: PhotoSize) => void;
}

const CameraCapture: React.FC<CameraCaptureProps> = ({ onCapture, selectedSize, onSizeChange }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string>('');
  const [countdown, setCountdown] = useState<number | null>(null);

  const [devices, setDevices] = useState<MediaDeviceInfo[]>([]);
  const [selectedDeviceId, setSelectedDeviceId] = useState<string>('');

  useEffect(() => {
    getDevices();
    startCamera();
    return () => stopCamera();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (selectedDeviceId) startCamera(selectedDeviceId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedDeviceId]);

  const getDevices = async () => {
    try {
      const allDevices = await navigator.mediaDevices.enumerateDevices();
      const videoDevices = allDevices.filter(device => device.kind === 'videoinput');
      setDevices(videoDevices);
      const canon = videoDevices.find(d => d.label.toLowerCase().includes('canon') || d.label.toLowerCase().includes('eos'));
      if (canon) setSelectedDeviceId(canon.deviceId);
    } catch (err) {
      console.error("Error enumerating devices", err);
    }
  };

  const startCamera = async (deviceId?: string) => {
    stopCamera();
    try {
      const constraints: MediaStreamConstraints = {
        video: {
          deviceId: deviceId ? { exact: deviceId } : undefined,
          width: { ideal: 1920 },
          height: { ideal: 1080 },
        },
        audio: false
      };
      const mediaStream = await navigator.mediaDevices.getUserMedia(constraints);
      setStream(mediaStream);
      if (videoRef.current) videoRef.current.srcObject = mediaStream;
      setError('');
    } catch (err) {
      setError('Không thể truy cập camera. Kiểm tra kết nối.');
    }
  };

  const stopCamera = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
    }
  };

  const handleCaptureClick = () => {
    setCountdown(3);
    const interval = setInterval(() => {
      setCountdown(prev => {
        if (prev === 1) {
          clearInterval(interval);
          captureFrame();
          return null;
        }
        return prev ? prev - 1 : null;
      });
    }, 1000);
  };

  const captureFrame = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      const context = canvas.getContext('2d');

      if (context) {
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        context.translate(canvas.width, 0);
        context.scale(-1, 1); 
        context.drawImage(video, 0, 0, canvas.width, canvas.height);
        context.setTransform(1, 0, 0, 1, 0, 0);
        const dataUrl = canvas.toDataURL('image/png', 1.0); // PNG preferred
        onCapture(dataUrl);
      }
    }
  };

  // Determine Aspect Ratio
  const getAspectRatio = () => {
    switch (selectedSize) {
      case PhotoSize.SIZE_5X5: return 1; // Square
      case PhotoSize.SIZE_3X4: return 3/4;
      case PhotoSize.SIZE_4X6: return 4/6; // Same as 2/3
      default: return 3/4;
    }
  };

  const targetRatio = getAspectRatio();
  const isUSVisa = selectedSize === PhotoSize.SIZE_5X5;

  return (
    <div className="flex flex-col items-center justify-center h-full w-full bg-gray-900 relative">

      {/* Device Select */}
      <div className="absolute top-4 left-4 z-50 bg-black/50 p-2 rounded-lg backdrop-blur-sm">
        <select 
          value={selectedDeviceId}
          onChange={(e) => setSelectedDeviceId(e.target.value)}
          className="bg-gray-800 text-white text-sm border border-gray-600 rounded px-2 py-1 outline-none"
        >
          <option value="">-- Chọn Camera --</option>
          {devices.map((device, idx) => (
            <option key={device.deviceId || idx} value={device.deviceId}>
              {device.label || `Camera ${idx + 1}`}
            </option>
          ))}
        </select>
      </div>

      {error && <div className="absolute z-50 bg-red-500 text-white p-4 rounded-lg shadow-xl">{error}</div>}

      {/* Camera Feed */}
      <div className="relative h-[80vh] aspect-[3/4] overflow-hidden bg-black rounded-sm shadow-2xl border border-gray-700 flex items-center justify-center">
        <video
          ref={videoRef}
          autoPlay
          playsInline
          className="absolute inset-0 w-full h-full object-cover transform -scale-x-100" 
        />

        {/* GUIDES OVERLAY */}
        <div 
           className="relative border-2 border-brand-400/80 shadow-[0_0_0_9999px_rgba(0,0,0,0.7)] pointer-events-none"
           style={{
             height: isUSVisa ? '75%' : '90%', // Square for 5x5, rect for others
             aspectRatio: `${targetRatio}`,
           }}
        >
          {isUSVisa ? (
            // --- US VISA GUIDES (5x5) ---
            <svg viewBox="0 0 100 100" className="absolute inset-0 w-full h-full opacity-70">
              <line x1="50" y1="0" x2="50" y2="100" stroke="white" strokeWidth="0.5" strokeDasharray="2,2" />

              {/* Head should be between 50% and 69% height.
                  Top of head ~15% from top? Bottom of chin ~85%?
                  Let's draw an oval for the head area.
               */}
              <ellipse cx="50" cy="50" rx="30" ry="35" fill="none" stroke="yellow" strokeWidth="1" strokeDasharray="4,2" />
              <text x="50" y="10" fill="yellow" fontSize="3" textAnchor="middle">Đỉnh đầu (Top of Head)</text>
              <line x1="20" y1="12" x2="80" y2="12" stroke="yellow" strokeWidth="0.5" />

              <text x="50" y="90" fill="yellow" fontSize="3" textAnchor="middle">Cằm (Chin)</text>
              <line x1="30" y1="88" x2="70" y2="88" stroke="yellow" strokeWidth="0.5" />

              {/* Eyes must be between 56% and 69% from bottom (approx 31% to 44% from top) */}
              <rect x="20" y="35" width="60" height="10" fill="none" stroke="#3b82f6" strokeWidth="0.5" />
              <text x="82" y="40" fill="#3b82f6" fontSize="3">Vùng Mắt</text>
            </svg>
          ) : (
             // --- STANDARD ID GUIDES (3x4, 4x6) ---
            <svg viewBox="0 0 100 100" className="absolute inset-0 w-full h-full opacity-60">
              <line x1="50" y1="0" x2="50" y2="100" stroke="white" strokeWidth="0.5" strokeDasharray="2,2" />
              <line x1="20" y1="45" x2="80" y2="45" stroke="#3b82f6" strokeWidth="0.5" />
              <text x="82" y="46" fill="#3b82f6" fontSize="3">Mắt</text>
              <line x1="35" y1="12" x2="65" y2="12" stroke="red" strokeWidth="0.5" />
              <text x="67" y="13" fill="red" fontSize="3">Đỉnh đầu</text>
              <line x1="40" y1="78" x2="60" y2="78" stroke="red" strokeWidth="0.5" />
              <text x="62" y="79" fill="red" fontSize="3">Cằm</text>
              <ellipse cx="50" cy="45" rx="22" ry="33" fill="none" stroke="white" strokeWidth="1" strokeDasharray="4,2" />
              <path d="M 10 100 Q 25 85 50 85 Q 75 85 90 100" fill="none" stroke="white" strokeWidth="1" strokeDasharray="4,2" />
            </svg>
          )}

          <div className="absolute bottom-2 left-0 right-0 text-center text-white/90 text-xs font-mono bg-black/20 p-1">
