  onNew: () => void;
  onSaved?: () => void;
}

const PrintPreview: React.FC<PrintPreviewProps> = ({ 
  processedImage, 
  size, 
  settings, 
  onBack, 
  onNew,
  onSaved 
}) => {
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  // Grid config logic
  const is3x4 = size === PhotoSize.SIZE_3X4;
  const is5x5 = size === PhotoSize.SIZE_5X5;

  let cellWidth = '37mm';
  let cellHeight = '57mm';
  let totalPhotos = 8;

  if (is3x4) {
    cellWidth = '27mm';
    cellHeight = '37mm';
    totalPhotos = 16;
  } else if (is5x5) {
    // 5x5 cm -> 50mm. Paper 130mm wide -> 2 columns (100mm total).
    // Paper 180mm high -> 3 rows (150mm total).
    // Total 6 photos.
    cellWidth = '49mm'; // Slightly less than 50mm for margin safety
    cellHeight = '49mm';
    totalPhotos = 6;
  }

  // Determine how many photos to render based on requested quantity, but bounded by sheet capacity
  // For this simplified preview, we just fill the sheet as per standard ID printing service

  const handlePrint = () => {
    window.print();
  };

  const handleDownload = () => {
    const link = document.createElement('a');
    link.href = processedImage;
    link.download = `ID-Photo-${size}-${Date.now()}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
