const ImageEditor: React.FC<ImageEditorProps> = ({ 
  originalImage, 
  settings, 
  onUpdateSettings,
  onProcessedImage,
  onNext,
  onRetake
}) => {
  const [displayImage, setDisplayImage] = useState<string>(originalImage);
  const [isProcessing, setIsProcessing] = useState(false);
  const [clothingInput, setClothingInput] = useState('');
  const [genderTab, setGenderTab] = useState<'male' | 'female'>('male');
  const [apiError, setApiError] = useState('');

  // Apply visual CSS filters instantly
  const filterStyle = {
    filter: `brightness(${settings.brightness}%) contrast(${settings.contrast}%) saturate(110%) blur(${settings.smoothness}px)`,
  };

  // Helper to handle AI processing requests
  const handleAIProcessing = async (targetBg: BackgroundType, targetClothing?: string) => {
    setIsProcessing(true);
    setApiError('');
    try {
      // If we are just reverting to original bg and no clothes change, revert to captured
      if (targetBg === BackgroundType.ORIGINAL && !targetClothing) {
        setDisplayImage(originalImage);
        onUpdateSettings({ ...settings, background: targetBg, clothingPrompt: undefined });
      } else {
        // Call Gemini
        const result = await processIDPhoto(originalImage, targetBg, targetClothing);
        setDisplayImage(result);
        onUpdateSettings({ ...settings, background: targetBg, clothingPrompt: targetClothing });
      }
    } catch (err: any) {
      setApiError(err.message || "Có lỗi xảy ra khi xử lý ảnh.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleClothingSubmit = () => {
    if (!clothingInput.trim()) return;
    handleAIProcessing(settings.background, clothingInput);
  };

  const handlePresetClick = (prompt: string) => {
    setClothingInput(prompt);
    handleAIProcessing(settings.background, prompt);
  };

  // When clicking Next, we need to apply the CSS filters permanently to a canvas and pass that forward
  const handleFinish = () => {
    const canvas = document.createElement('canvas');
    const img = new Image();
    img.src = displayImage;
    img.onload = () => {
      // Create a canvas with the target ratio
      let aspectRatio;
      if (settings.size === PhotoSize.SIZE_5X5) {
        aspectRatio = 1; // Square 1:1
      } else {
        aspectRatio = settings.size === PhotoSize.SIZE_3X4 ? 3/4 : 4/6;
      }

      // Calculate crop to fit ratio centered
      let sourceW = img.width;
      let sourceH = img.height;
      let targetW, targetH;
      let offsetX = 0;
      let offsetY = 0;

      if (sourceW / sourceH > aspectRatio) {
        // Image is wider than needed
        targetH = sourceH;
        targetW = sourceH * aspectRatio;
        offsetX = (sourceW - targetW) / 2;
      } else {
        // Image is taller than needed
        targetW = sourceW;
        targetH = sourceW / aspectRatio;
        offsetY = (sourceH - targetH) / 2;
      }

      // High res output
      canvas.width = targetW;
      canvas.height = targetH;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        // Apply filters
        ctx.filter = `brightness(${settings.brightness}%) contrast(${settings.contrast}%) saturate(110%) blur(${settings.smoothness}px)`;

        ctx.drawImage(
          img, 
          offsetX, offsetY, targetW, targetH, // Source
          0, 0, targetW, targetH // Dest
        );

        onProcessedImage(canvas.toDataURL('image/png'));
        onNext();
      }
    };
  };

  return (
    <div className="flex flex-col md:flex-row h-full w-full bg-gray-50 overflow-hidden">

      {/* Sidebar Controls */}
      <div className="w-full md:w-96 bg-white shadow-lg p-6 flex flex-col gap-6 overflow-y-auto z-10 border-r border-gray-200">

        <div>
          <h2 className="text-xl font-bold text-gray-800 mb-4 flex items-center gap-2">
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4m6 6v10m6-2a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4"></path></svg>
            Chỉnh sửa
          </h2>

          {/* Background Selection */}
          <div className="mb-6">
            <label className="block text-sm font-medium text-gray-700 mb-2">Màu nền</label>
            <div className="grid grid-cols-3 gap-2">
              <button 
                onClick={() => handleAIProcessing(BackgroundType.ORIGINAL, settings.clothingPrompt)}
                className={`h-10 rounded border flex items-center justify-center text-xs ${settings.background === BackgroundType.ORIGINAL ? 'ring-2 ring-brand-500 border-transparent' : 'border-gray-300'}`}
              >
                Gốc
              </button>
              <button 
                onClick={() => handleAIProcessing(BackgroundType.WHITE, settings.clothingPrompt)}
                className={`h-10 rounded border flex items-center justify-center text-xs bg-white ${settings.background === BackgroundType.WHITE ? 'ring-2 ring-brand-500 border-gray-200' : 'border-gray-300'}`}
              >
                Trắng
              </button>
              <button 
                onClick={() => handleAIProcessing(BackgroundType.BLUE, settings.clothingPrompt)}
                className={`h-10 rounded border flex items-center justify-center text-xs bg-[#0057B7] text-white ${settings.background === BackgroundType.BLUE ? 'ring-2 ring-brand-500 border-transparent' : 'border-gray-300'}`}
              >
                Xanh
              </button>
            </div>
            <p className="text-xs text-gray-500 mt-1">*Sử dụng AI để tách nền</p>
          </div>

          {/* Clothes Changer UI */}
          <div className="mb-6 p-4 bg-blue-50 rounded-lg border border-blue-100">
            <label className="block text-sm font-bold text-blue-800 mb-2">Thay trang phục (AI)</label>

            {/* Gender Tabs */}
            <div className="flex mb-3 border-b border-blue-200">
              <button 
                onClick={() => setGenderTab('male')}
                className={`flex-1 py-1 text-sm font-medium ${genderTab === 'male' ? 'text-blue-700 border-b-2 border-blue-700' : 'text-blue-400 hover:text-blue-600'}`}
              >
                Nam
              </button>
              <button 
                onClick={() => setGenderTab('female')}
                className={`flex-1 py-1 text-sm font-medium ${genderTab === 'female' ? 'text-blue-700 border-b-2 border-blue-700' : 'text-blue-400 hover:text-blue-600'}`}
              >
                Nữ
              </button>
            </div>

            {/* Presets Grid */}
            <div className="grid grid-cols-2 gap-2 mb-3">
              {CLOTHING_CATALOG[genderTab].map((item) => (
                <button
                  key={item.id}
                  onClick={() => handlePresetClick(item.prompt)}
                  disabled={isProcessing}
                  className={`py-2 px-1 text-xs rounded border shadow-sm transition-all hover:shadow hover:scale-[1.02] disabled:opacity-50 ${item.color}`}
                >
                  {item.label}
                </button>
              ))}
            </div>

            {/* Manual Input Override */}
            <div className="flex gap-2 mb-1">
              <input 
                type="text"
                placeholder="Hoặc nhập mô tả tùy chỉnh..."
                value={clothingInput}
                onChange={(e) => setClothingInput(e.target.value)}
                className="flex-1 rounded border-gray-300 text-xs p-2 focus:ring-blue-500 focus:border-blue-500"
              />
              <button 
                onClick={handleClothingSubmit}
                disabled={isProcessing || !clothingInput}
                className="px-3 py-1 bg-blue-600 text-white rounded text-xs font-medium hover:bg-blue-700 disabled:opacity-50"
              >
                Gửi
              </button>
            </div>
            <p className="text-[10px] text-blue-600 mt-1 italic">AI sẽ giữ nguyên khuôn mặt và thay thế phần thân áo.</p>
          </div>

          {/* Sliders */}
          <div className="space-y-4 mb-6">
            <div>
              <label className="flex justify-between text-sm font-medium text-gray-700">
                Làm sáng da
                <span className="text-gray-400">{settings.brightness}%</span>
              </label>
              <input 
                type="range" min="80" max="150" 
                value={settings.brightness}
                onChange={(e) => onUpdateSettings({...settings, brightness: Number(e.target.value)})}
                className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-brand-600"
              />
            </div>
            <div>
              <label className="flex justify-between text-sm font-medium text-gray-700">
                Độ tương phản
                <span className="text-gray-400">{settings.contrast}%</span>
              </label>
              <input 
                type="range" min="80" max="150" 
                value={settings.contrast}
                onChange={(e) => onUpdateSettings({...settings, contrast: Number(e.target.value)})}
                className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-brand-600"
              />
            </div>
            <div>
              <label className="flex justify-between text-sm font-medium text-gray-700">
                Làm mịn (Beauty)
                <span className="text-gray-400">{settings.smoothness}</span>
              </label>
              <input 
                type="range" min="0" max="3" step="0.1"
                value={settings.smoothness}
                onChange={(e) => onUpdateSettings({...settings, smoothness: Number(e.target.value)})}
                className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-brand-600"
              />
            </div>
          </div>

          {apiError && (
             <div className="p-3 bg-red-100 text-red-700 text-sm rounded mb-4">
               {apiError}
             </div>
          )}

        </div>

        <div className="mt-auto flex flex-col gap-3">
          <button 
            onClick={handleFinish}
            disabled={isProcessing}
            className="w-full py-3 bg-brand-600 text-white rounded-lg font-bold shadow hover:bg-brand-700 transition disabled:opacity-50"
          >
            Tiếp tục & In ấn
          </button>
          <button 
            onClick={onRetake}
            className="w-full py-3 bg-white text-gray-600 border border-gray-300 rounded-lg font-medium hover:bg-gray-50 transition"
          >
            Chụp lại
          </button>
        </div>
      </div>

      {/* Main Preview Area */}
      <div className="flex-1 bg-gray-100 flex items-center justify-center p-8 relative">
        <div className="relative shadow-2xl rounded-sm overflow-hidden bg-white border-8 border-white">

          {isProcessing && (
            <div className="absolute inset-0 bg-white/80 z-20 flex flex-col items-center justify-center">
              <div className="animate-spin rounded-full h-12 w-12 border-4 border-brand-500 border-t-transparent"></div>
              <p className="mt-4 text-brand-700 font-medium animate-pulse">Đang xử lý AI...</p>
              <p className="text-xs text-gray-500 mt-2">Vui lòng chờ trong giây lát</p>
            </div>
          )}

          <img 
            src={displayImage} 
            alt="Preview" 
            style={{
               ...filterStyle,
               maxHeight: '70vh',
               maxWidth: '100%',
               objectFit: 'contain'
            }}
          />

          {/* Crop Overlay Guide (Visual only) */}
          <div className="absolute inset-0 border-2 border-dashed border-red-400/50 pointer-events-none"></div>
          <div className="absolute top-2 left-2 bg-black/50 text-white text-xs px-2 py-1 rounded">
            Hệ màu: RGB
          </div>
          <div className="absolute top-2 right-2 bg-brand-600 text-white text-xs px-2 py-1 rounded">
            Khổ: {settings.size === PhotoSize.SIZE_5X5 ? '5x5 cm' : settings.size === PhotoSize.SIZE_3X4 ? '3x4 cm' : '4x6 cm'}
          </div>
        </div>
      </div>
    </div>
  );
};

export default ImageEditor;

export enum PhotoSize {
  SIZE_3X4 = '3x4',
  SIZE_4X6 = '4x6',
  SIZE_5X5 = '5x5' // US Visa / International
}

export enum BackgroundType {
  WHITE = 'white',
  BLUE = 'blue',
  ORIGINAL = 'original'
}

export enum AppStep {
  CONFIG = 'config', // New start screen
  CAPTURE = 'capture',
  EDIT = 'edit',
  PRINT = 'print'
}

export interface PhotoSettings {
  size: PhotoSize;
  background: BackgroundType;
  brightness: number;
  contrast: number;
  smoothness: number; 
  clothingPrompt?: string;
  printQuantity: number;
  phoneNumber?: string; // New: Zalo/Contact number
}

export interface SavedPhoto {
  id: string;
  dataUrl: string;
  timestamp: number;
  settings: PhotoSettings;
}

import React, { useState } from 'react';
import { PhotoSettings, PhotoSize } from '../types';
import { savePhotoToCloud } from '../services/databaseService';

interface PrintPreviewProps {
  processedImage: string;
  size: PhotoSize;
  settings: PhotoSettings;
  onBack: () => void;
  onNew: () => void;
  onSaved?: () => void;
}

export default function PrintPreview({ 
  processedImage, 
  size, 
  settings, 
  onBack, 
  onNew,
  onSaved 
}: PrintPreviewProps) {
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  // Zalo & QR State
  const [phoneNumber, setPhoneNumber] = useState(settings.phoneNumber || '');
  const [isSendingZalo, setIsSendingZalo] = useState(false);
  const [showQR, setShowQR] = useState(false);

  // Grid config logic
  const is3x4 = size === PhotoSize.SIZE_3X4;
  const is5x5 = size === PhotoSize.SIZE_5X5;

  let cellWidth = '37mm';
  let cellHeight = '57mm';
  let totalPhotos = 8;

  if (is3x4) {
    cellWidth = '27mm';
    cellHeight = '37mm';
    totalPhotos = 16;
  } else if (is5x5) {
    cellWidth = '49mm';
    cellHeight = '49mm';
    totalPhotos = 6;
  }

  const handlePrint = () => {
    window.print();
  };

  const handleDownload = () => {
    const link = document.createElement('a');
    link.href = processedImage;
    link.download = `ID-Photo-${size}-${Date.now()}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleSaveToDB = async () => {
    setIsSaving(true);
    // Include phone number in settings before saving
    const currentSettings = { ...settings, phoneNumber };

    const success = await savePhotoToCloud({
      id: Date.now().toString(),
      dataUrl: processedImage,
      timestamp: Date.now(),
      settings: currentSettings
    });

    setIsSaving(false);
    if (success) {
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
      if (onSaved) onSaved();
    } else {
      alert("Lỗi khi lưu vào cơ sở dữ liệu");
    }
  };

  /**
   * ZALO INTEGRATION STUB
   * 
   * Đây là nơi bạn sẽ tích hợp API của Zalo OA (Official Account) hoặc dịch vụ SMS Gateway.
   * Quy trình thực tế:
   * 1. Upload ảnh lên Server/Cloud Storage -> Lấy URL công khai (Public URL).
   * 2. Gọi API Zalo với payload: { phone: phoneNumber, image_url: publicUrl, message: "Ảnh thẻ của bạn" }
   */
  const handleSendZalo = async () => {
    if (!phoneNumber || phoneNumber.length < 9) {
      alert("Vui lòng nhập số điện thoại hợp lệ.");
      return;
    }

    setIsSendingZalo(true);

    try {
      // --- MÔ PHỎNG GỌI API (SERVER SIDE LOGIC) ---
      console.log("Đang chuẩn bị gửi Zalo tới:", phoneNumber);

      // Bước 1: Giả lập upload ảnh lấy URL
      await new Promise(resolve => setTimeout(resolve, 1000)); // Delay upload
      const mockImageUrl = "https://your-cloud-storage.com/photo-id-123.jpg";

      // Bước 2: Giả lập gọi API Zalo
      // await axios.post('https://your-backend-api.com/send-zalo', { phone: phoneNumber, url: mockImageUrl });
      await new Promise(resolve => setTimeout(resolve, 1000)); // Delay send

      alert(`Đã gửi ảnh thành công tới Zalo: ${phoneNumber}\n(Đây là tính năng mô phỏng. Cần tích hợp Zalo OA API để hoạt động thực tế).`);
    } catch (error) {
      alert("Gửi thất bại. Vui lòng thử lại.");
    } finally {
      setIsSendingZalo(false);
    }
  };

  // Generate a mock QR Code URL (In production, this would be the actual URL of the saved image)
  // Using a public QR API for demonstration
  const qrCodeUrl = `https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=https://photobooth-demo.com/download/${Date.now()}`;

  return (
    <div className="flex flex-col h-full bg-gray-100 relative">

      {/* QR Code Modal */}
      {showQR && (
        <div className="fixed inset-0 z-50 bg-black/60 flex items-center justify-center p-4 backdrop-blur-sm" onClick={() => setShowQR(false)}>
          <div className="bg-white rounded-2xl p-6 max-w-sm w-full shadow-2xl text-center" onClick={e => e.stopPropagation()}>
            <h3 className="text-xl font-bold text-gray-800 mb-2">Quét mã để tải ảnh</h3>
            <p className="text-sm text-gray-500 mb-4">Sử dụng Camera hoặc Zalo để quét</p>

            <div className="bg-white p-2 rounded-xl border-2 border-brand-100 inline-block mb-4">
               <img src={qrCodeUrl} alt="QR Download" className="w-48 h-48" />
            </div>

            <p className="text-xs text-gray-400 mb-6">Link tải sẽ hết hạn sau 24h (Mô phỏng)</p>

            <button 
              onClick={() => setShowQR(false)}
              className="w-full py-2 bg-gray-100 hover:bg-gray-200 text-gray-800 rounded-lg font-bold"
            >
              Đóng
            </button>
          </div>
        </div>
      )}

      {/* Header */}
      <header className="bg-white shadow-sm p-4 flex justify-between items-center no-print">
        <h1 className="text-xl font-bold text-gray-800">Xem trước bản in (Epson L8050)</h1>
        <div className="flex gap-2">
          <button onClick={onBack} className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded">
            Chỉnh sửa lại
          </button>
          <button onClick={onNew} className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded">
            Khách mới
          </button>
        </div>
      </header>

      <div className="flex-1 overflow-auto p-8 flex justify-center items-start gap-8">

        {/* Print Canvas Container */}
        <div 
          className="bg-white shadow-2xl overflow-hidden relative print:shadow-none" 
          style={{ 
            width: '130mm', 
            height: '180mm', 
            minWidth: '130mm', 
            minHeight: '180mm',
            border: '1px solid #e5e7eb'
          }}
        >

            {/* Grid Layout */}
            <div className={`w-full h-full p-[5mm] flex flex-wrap content-start gap-[2mm] ${is5x5 ? 'justify-center content-center' : ''}`}>
              {Array.from({ length: totalPhotos }).map((_, i) => (
                <div 
                  key={i} 
                  className="overflow-hidden border border-gray-200"
                  style={{
                    width: cellWidth,
                    height: cellHeight,
                  }}
                >
                  <img 
                    src={processedImage} 
                    className="w-full h-full object-cover" 
                    alt="ID Photo"
                  />
                </div>
              ))}
            </div>

            {/* Print Marks / Footer */}
