              disabled={isSaving || saveSuccess}
              className={`flex items-center justify-center gap-2 w-full py-2 rounded-lg font-medium text-sm transition ${saveSuccess ? 'bg-green-100 text-green-700' : 'bg-gray-100 hover:bg-gray-200 text-gray-700'}`}
            >
              {isSaving ? 'Đang lưu...' : saveSuccess ? 'Đã lưu CSDL' : 'Lưu vào CSDL'}
            </button>
          </div>

          {/* Section: Digital Share */}
          <div>
            <h3 className="font-bold text-gray-800 mb-3 flex items-center gap-2">
              <svg className="w-5 h-5 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 18h.01M8 21h8a2 2 0 002-2V5a2 2 0 00-2-2H8a2 2 0 00-2 2v14a2 2 0 002 2z"></path></svg>
              Gửi file mềm
            </h3>

            {/* Zalo Input */}
            <div className="mb-4">
              <label className="block text-xs font-semibold text-gray-600 mb-1">Số điện thoại / Zalo</label>
              <div className="flex gap-2">
                <input 
                  type="tel" 
                  value={phoneNumber}
