import { GoogleGenAI } from "@google/genai";
import { BackgroundType } from "../types";

const API_KEY = process.env.API_KEY || '';

// Initialize the client
const ai = new GoogleGenAI({ apiKey: API_KEY });

/**
 * Processes the image to remove background, change background color, 
 * or change clothes using Gemini's vision capabilities.
 */
export const processIDPhoto = async (
  imageBase64: string, 
  bgType: BackgroundType, 
  clothingPrompt: string | undefined
): Promise<string> => {
  if (!API_KEY) {
    throw new Error("API Key chưa được cấu hình.");
  }

  // Clean base64 string
  const cleanBase64 = imageBase64.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  let prompt = `Bạn là hệ thống AI chuyên xử lý ảnh thẻ và ảnh visa.
Nhiệm vụ của bạn CHỈ LÀ XỬ LÝ ẢNH.

=====================
CÁC BƯỚC XỬ LÝ BẮT BUỘC
=====================
Thực hiện tuần tự:

1. Nhận diện khuôn mặt người:
- Giữ nguyên hoàn toàn khuôn mặt, tóc và đầu (Không được thay đổi nhận diện sinh trắc học).
- Đảm bảo mặt nhìn thẳng.

2. Kiểm tra & chuẩn hóa phông nền:
- Tách chủ thể.`;

  // Background specific logic
  if (bgType === BackgroundType.WHITE) {
    prompt += `
- Chuyển phông nền sang màu trắng tuyệt đối (#FFFFFF).
- Không bóng đổ, không nhiễu, không gradient.`;
  } else if (bgType === BackgroundType.BLUE) {
    prompt += `
- Chuyển phông nền sang màu xanh dương chuẩn ảnh thẻ (Blue #0057B7).
- Màu sắc đồng nhất, không gradient.`;
  } else {
    prompt += `
- Giữ nguyên phông nền nhưng làm sạch nhiễu.`;
  }

  prompt += `
3. Căn chỉnh:
- Khuôn mặt nằm chính giữa ảnh.
- Trục khuôn mặt thẳng đứng.`;

  // Clothing logic
  if (clothingPrompt) {
    prompt += `
4. Thay trang phục (NẾU CÓ):
- Thay đổi trang phục thành: ${clothingPrompt}.
- Đảm bảo cổ áo và vai khớp tự nhiên với đầu.`;
  }

  prompt += `
=====================
ĐẦU RA
=====================
- Chỉ trả về hình ảnh đã xử lý.
- Định dạng: JPEG/PNG chất lượng cao.
- Hệ màu: RGB.
- Tỷ lệ khuôn mặt chuẩn ảnh thẻ (khoảng cách từ mắt lên mép trên ~2/3 khoảng cách từ mắt xuống mép dưới).
`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image', // Using flash-image for good balance of speed and editing capability
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: cleanBase64
            }
          },
          {
            text: prompt
          }
        ]
      }
    });

    // Extract images from response parts
    const parts = response.candidates?.[0]?.content?.parts;
    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
          return `data:image/jpeg;base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("Không nhận được dữ liệu ảnh từ Gemini.");

  } catch (error) {
    console.error("Gemini processing error:", error);
    throw error;
  }
};

import React, { useRef, useState, useEffect } from 'react';
import { PhotoSize } from '../types';

interface CameraCaptureProps {
  onCapture: (imageSrc: string) => void;
  selectedSize: PhotoSize;
  onSizeChange: (size: PhotoSize) => void;
}

// Mock AI States for UX Demonstration
type ValidationStatus = 'scanning' | 'detecting' | 'error' | 'valid';

const CameraCapture: React.FC<CameraCaptureProps> = ({ onCapture, selectedSize, onSizeChange }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string>('');
  const [countdown, setCountdown] = useState<number | null>(null);

  const [devices, setDevices] = useState<MediaDeviceInfo[]>([]);
  const [selectedDeviceId, setSelectedDeviceId] = useState<string>('');

  // AI Validation State
  const [validationStatus, setValidationStatus] = useState<ValidationStatus>('scanning');
  const [feedbackMessage, setFeedbackMessage] = useState<string>('Đang tìm khuôn mặt...');

  // Simulation Loop for "AI Detection" UX
  useEffect(() => {
    // Reset status when size changes
    setValidationStatus('scanning');
    setFeedbackMessage('Đang quét sinh trắc học...');

    const timers: NodeJS.Timeout[] = [];

    // Simulate flow: Scanning -> Detecting -> Analysis -> Ready
    // In a real app, this would be replaced by actual FaceAPI/MediaPipe callbacks
    timers.push(setTimeout(() => {
      setValidationStatus('detecting');
      setFeedbackMessage('Đang phân tích tỷ lệ...');
    }, 1000));

    timers.push(setTimeout(() => {
      // Simulate a random check (usually valid for demo purposes)
      setValidationStatus('valid');
      setFeedbackMessage('ĐẠT CHUẨN');
    }, 2500));

    return () => timers.forEach(clearTimeout);
  }, [selectedSize]);

  useEffect(() => {
    getDevices();
    startCamera();
    return () => stopCamera();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (selectedDeviceId) startCamera(selectedDeviceId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedDeviceId]);

  const getDevices = async () => {
    try {
      const allDevices = await navigator.mediaDevices.enumerateDevices();
      const videoDevices = allDevices.filter(device => device.kind === 'videoinput');
      setDevices(videoDevices);
      const canon = videoDevices.find(d => d.label.toLowerCase().includes('canon') || d.label.toLowerCase().includes('eos'));
      if (canon) setSelectedDeviceId(canon.deviceId);
    } catch (err) {
      console.error("Error enumerating devices", err);
    }
  };

  const startCamera = async (deviceId?: string) => {
    stopCamera();
    try {
      const constraints: MediaStreamConstraints = {
        video: {
          deviceId: deviceId ? { exact: deviceId } : undefined,
          width: { ideal: 1920 },
          height: { ideal: 1080 },
        },
        audio: false
      };
      const mediaStream = await navigator.mediaDevices.getUserMedia(constraints);
      setStream(mediaStream);
      if (videoRef.current) videoRef.current.srcObject = mediaStream;
      setError('');
    } catch (err) {
      setError('Không thể truy cập camera. Kiểm tra kết nối.');
    }
  };

  const stopCamera = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
    }
  };

  const handleCaptureClick = () => {
    if (validationStatus !== 'valid') return;

    setCountdown(3);
    const interval = setInterval(() => {
      setCountdown(prev => {
        if (prev === 1) {
          clearInterval(interval);
          captureFrame();
          return null;
        }
        return prev ? prev - 1 : null;
      });
    }, 1000);
  };

  const captureFrame = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      const context = canvas.getContext('2d');

      if (context) {
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        context.translate(canvas.width, 0);
        context.scale(-1, 1); 
        context.drawImage(video, 0, 0, canvas.width, canvas.height);
        context.setTransform(1, 0, 0, 1, 0, 0);
        const dataUrl = canvas.toDataURL('image/png', 1.0); // PNG preferred
        onCapture(dataUrl);
      }
    }
  };

  // Determine configuration based on size
  const isUSVisa = selectedSize === PhotoSize.SIZE_5X5;
  const targetRatio = isUSVisa ? 1 : (selectedSize === PhotoSize.SIZE_3X4 ? 3/4 : 4/6);

  // Status Colors
  const getStatusColor = () => {
    switch (validationStatus) {
      case 'valid': return 'border-green-500 shadow-[0_0_20px_rgba(34,197,94,0.6)]';
      case 'error': return 'border-red-500 shadow-[0_0_20px_rgba(239,68,68,0.6)]';
      default: return 'border-blue-400 shadow-[0_0_20px_rgba(96,165,250,0.4)]';
    }
  };

  return (
    <div className="flex flex-col items-center justify-center h-full w-full bg-gray-900 relative select-none">

      {/* Top Bar: Device & Status */}
      <div className="absolute top-0 left-0 right-0 z-50 p-4 flex justify-between items-start bg-gradient-to-b from-black/80 to-transparent pb-12">
        <select 
          value={selectedDeviceId}
          onChange={(e) => setSelectedDeviceId(e.target.value)}
          className="bg-black/50 text-white text-xs border border-gray-600 rounded px-3 py-1.5 outline-none backdrop-blur-md"
        >
          <option value="">-- Chọn Camera --</option>
          {devices.map((device, idx) => (
            <option key={device.deviceId || idx} value={device.deviceId}>
              {device.label || `Camera ${idx + 1}`}
            </option>
          ))}
        </select>

        {/* Realtime Feedback Popup */}
        <div className={`
          px-4 py-2 rounded-lg backdrop-blur-md border flex items-center gap-2 transition-all duration-300
          ${validationStatus === 'valid' ? 'bg-green-500/20 border-green-500 text-green-100' : 
            validationStatus === 'error' ? 'bg-red-500/20 border-red-500 text-red-100' : 
            'bg-blue-500/20 border-blue-400 text-blue-100'}
        `}>
          {validationStatus === 'scanning' && <div className="animate-spin w-3 h-3 border-2 border-current border-t-transparent rounded-full" />}
          {validationStatus === 'valid' && <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg>}
          {validationStatus === 'error' && <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"></path></svg>}
          <span className="font-bold text-sm tracking-wide uppercase">{feedbackMessage}</span>
        </div>
      </div>

      {error && <div className="absolute z-50 bg-red-600 text-white p-4 rounded-lg shadow-xl font-bold animate-pulse">{error}</div>}

      {/* Camera Feed Container */}
      <div className={`relative h-[80vh] transition-all duration-300 ${isUSVisa ? 'aspect-square' : 'aspect-[3/4]'} bg-black rounded-lg overflow-hidden flex items-center justify-center`}>
        <video
          ref={videoRef}
          autoPlay
          playsInline
          className="absolute inset-0 w-full h-full object-cover transform -scale-x-100" 
        />

        {/* =============================================
            BIOMETRIC GUIDE OVERLAY (SVG)
           ============================================= */}
        <div 
           className={`relative z-10 w-full h-full border-2 transition-all duration-500 ${getStatusColor()}`}
        >
          {/* Scanning Line Animation */}
          {validationStatus === 'scanning' && (
            <div className="absolute top-0 left-0 w-full h-1 bg-blue-400/80 shadow-[0_0_15px_rgba(96,165,250,1)] animate-[scan_2s_ease-in-out_infinite]" />
          )}

          {isUSVisa ? (
            // --- VISA MỸ (5x5) GUIDE ---
            <svg viewBox="0 0 100 100" className="absolute inset-0 w-full h-full opacity-80 pointer-events-none">
              {/* Central Axis */}
              <line x1="50" y1="0" x2="50" y2="100" stroke="rgba(255,255,255,0.5)" strokeWidth="0.3" strokeDasharray="2,2" />

              {/* Head Size Zone (50-69%) 
                  Head Top (Min): ~15% from top
                  Chin Bottom (Max): ~85% from top
              */}
              <ellipse cx="50" cy="50" rx="28" ry="35" fill="none" stroke={validationStatus === 'valid' ? '#22c55e' : 'yellow'} strokeWidth="0.8" strokeDasharray="4,2" />

              {/* Eye Zone (56% to 69% from bottom => 31% to 44% from top) */}
              <rect x="15" y="31" width="70" height="13" fill="rgba(59, 130, 246, 0.1)" stroke="#3b82f6" strokeWidth="0.5" />

              {/* Text Guides */}
              <text x="50" y="10" fill="white" fontSize="2.5" textAnchor="middle" fontWeight="bold">ĐỈNH ĐẦU</text>
              <line x1="40" y1="12" x2="60" y2="12" stroke="white" strokeWidth="0.5" />

              <text x="90" y="38" fill="#3b82f6" fontSize="2.5" textAnchor="middle">MẮT</text>

              <text x="50" y="92" fill="white" fontSize="2.5" textAnchor="middle" fontWeight="bold">CẰM</text>
              <line x1="40" y1="88" x2="60" y2="88" stroke="white" strokeWidth="0.5" />
            </svg>
          ) : (
             // --- STANDARD ID (3x4 / 4x6) GUIDE ---
            <svg viewBox="0 0 100 100" className="absolute inset-0 w-full h-full opacity-80 pointer-events-none">
              {/* Central Axis */}
              <line x1="50" y1="0" x2="50" y2="100" stroke="rgba(255,255,255,0.5)" strokeWidth="0.3" strokeDasharray="2,2" />

              {/* Face Oval (approx 75% height) */}
              <ellipse cx="50" cy="48" rx="24" ry="34" fill="none" stroke={validationStatus === 'valid' ? '#22c55e' : 'white'} strokeWidth="0.8" strokeDasharray="6,4" />

              {/* Eye Line (approx 2/3 up from bottom of face area, effectively ~45% from top of image) */}
              <line x1="20" y1="45" x2="80" y2="45" stroke="#3b82f6" strokeWidth="0.5" />
              <text x="85" y="46" fill="#3b82f6" fontSize="2.5" fontWeight="bold">MẮT</text>

              {/* Top/Bottom Markers */}
              <path d="M 40 12 L 60 12" stroke="red" strokeWidth="0.5" />
              <text x="50" y="10" fill="red" fontSize="2.5" textAnchor="middle">ĐỈNH ĐẦU</text>

              <path d="M 42 82 L 58 82" stroke="red" strokeWidth="0.5" />
              <text x="50" y="86" fill="red" fontSize="2.5" textAnchor="middle">CẰM</text>

              {/* Shoulder Hints */}
              <path d="M 15 100 Q 30 85 50 85 Q 70 85 85 100" fill="none" stroke="rgba(255,255,255,0.3)" strokeWidth="0.5" strokeDasharray="2,2" />
            </svg>
          )}

          {/* Type Label */}
          <div className="absolute bottom-2 left-0 right-0 text-center">
             <span className="bg-black/40 text-white/90 text-xs font-mono px-2 py-1 rounded border border-white/20">
               {isUSVisa ? 'VISA MỸ 5x5 (VUÔNG)' : (selectedSize === PhotoSize.SIZE_3X4 ? 'THẺ 3x4 (DỌC)' : 'HỘ CHIẾU 4x6 (DỌC)')}
             </span>
          </div>
        </div>

        {/* Countdown Overlay */}
        {countdown !== null && (
          <div className="absolute inset-0 flex items-center justify-center bg-black/60 z-40 backdrop-blur-sm">
            <div className="relative">
               <span className="text-[120px] font-bold text-white animate-ping absolute opacity-20">{countdown}</span>
               <span className="text-[120px] font-bold text-white relative">{countdown}</span>
            </div>
          </div>
        )}
      </div>

      {/* Capture Controls */}
      <div className="absolute bottom-8 left-0 right-0 flex flex-col justify-end items-center gap-4">

        {/* Instruction Text */}
        <div className={`text-sm font-medium transition-colors duration-300 ${validationStatus === 'valid' ? 'text-green-400' : 'text-gray-400'}`}>
           {validationStatus === 'valid' ? 'Khuôn mặt đã được căn chỉnh.' : 'Vui lòng di chuyển khuôn mặt vào khung hình.'}
        </div>

        {/* Shutter Button */}
        <button
          onClick={handleCaptureClick}
          disabled={validationStatus !== 'valid' || countdown !== null}
          className={`
            w-20 h-20 rounded-full border-4 transition-all duration-300 flex items-center justify-center shadow-2xl
            ${validationStatus === 'valid' 
              ? 'bg-white border-gray-200 hover:border-brand-500 hover:scale-105 active:scale-95 cursor-pointer' 
              : 'bg-gray-600 border-gray-700 opacity-50 cursor-not-allowed'}
          `}
          aria-label="Chụp ảnh"
        >
           <div className={`w-16 h-16 rounded-full transition-all duration-300 ${validationStatus === 'valid' ? 'bg-brand-600' : 'bg-gray-500'}`}></div>
        </button>
      </div>

      <canvas ref={canvasRef} className="hidden" />

      {/* Global Style for Scan Animation */}
      <style>{`
        @keyframes scan {
          0% { top: 0%; opacity: 0; }
          10% { opacity: 1; }
          90% { opacity: 1; }
          100% { top: 100%; opacity: 0; }
        }
      `}</style>
    </div>
  );
};

