      <div className="absolute bottom-8 left-0 right-0 flex flex-col justify-end items-center gap-4 z-50 pointer-events-auto">

        {/* Instruction Text */}
        <div className={`text-sm font-medium transition-colors duration-300 drop-shadow-md ${validationStatus === 'valid' ? 'text-green-400' : 'text-gray-400'}`}>
           {validationStatus === 'valid' ? 'Khuôn mặt đã được căn chỉnh.' : 'Vui lòng di chuyển khuôn mặt vào khung hình.'}
        </div>

        {/* Shutter Button */}
        <button
          onClick={handleCaptureClick}
          disabled={validationStatus !== 'valid' || countdown !== null}
          className={`
            w-20 h-20 rounded-full border-4 transition-all duration-300 flex items-center justify-center shadow-2xl
            ${validationStatus === 'valid' 
              ? 'bg-white border-gray-200 hover:border-brand-500 hover:scale-105 active:scale-95 cursor-pointer' 
              : 'bg-gray-600 border-gray-700 opacity-50 cursor-not-allowed'}
          `}
          aria-label="Chụp ảnh"
        >
           <div className={`w-16 h-16 rounded-full transition-all duration-300 ${validationStatus === 'valid' ? 'bg-brand-600' : 'bg-gray-500'}`}></div>
        </button>
      </div>

      <canvas ref={canvasRef} className="hidden" />

      {/* Global Style for Scan Animation */}
      <style>{`
        @keyframes scan {
          0% { top: 0%; opacity: 0; }
          10% { opacity: 1; }
          90% { opacity: 1; }
          100% { top: 100%; opacity: 0; }
        }
      `}</style>
    </div>
  );
};

