import { GoogleGenAI } from "@google/genai";
import { BackgroundType, BeautySettings } from "../types";

const API_KEY = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey: API_KEY });

/**
 * Processes the ID photo with strict biometric preservation rules.
 */
export const processIDPhoto = async (
  imageBase64: string, 
  bgType: BackgroundType, 
  clothingPrompt: string | undefined,
  beautySettings: BeautySettings
): Promise<string> => {
  if (!API_KEY) {
    throw new Error("API Key chưa được cấu hình.");
  }

  const cleanBase64 = imageBase64.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  // Constructing a structured prompt
  let prompt = `ROLE: Hệ thống AI xử lý ảnh sinh trắc học chuyên nghiệp (Passport/Visa/ID).
INPUT: Ảnh chân dung người.
OUTPUT: Ảnh đã xử lý tiêu chuẩn, giữ nguyên nhận dạng.

=========================================
QUY TẮC BẤT DI BẤT DỊCH (NGHIÊM CẤM VI PHẠM)
=========================================
1. KHÔNG ĐƯỢC PHÉP thay đổi cấu trúc xương mặt, hình dáng mắt, mũi, miệng.
2. KHÔNG ĐƯỢC PHÉP xóa nốt ruồi, sẹo vĩnh viễn hoặc đặc điểm nhận dạng bẩm sinh.
3. KHÔNG ĐƯỢC PHÉP làm biến dạng khuôn mặt (warping/liquify).
4. Giữ nguyên hướng nhìn và biểu cảm gốc.

=========================================
YÊU CẦU XỬ LÝ (THỰC HIỆN TUẦN TỰ)
=========================================

BƯỚC 1: XỬ LÝ PHÔNG NỀN (BACKGROUND)
`;

  // Background Logic
  if (bgType === BackgroundType.WHITE) {
    prompt += `- Tách nền chủ thể cực kỳ chính xác (từng sợi tóc).
- Thay thế bằng nền MÀU TRẮNG TUYỆT ĐỐI (#FFFFFF).
- Không có bóng đổ (drop shadow), không gradient.`;
  } else if (bgType === BackgroundType.BLUE) {
    prompt += `- Tách nền chủ thể.
- Thay thế bằng nền XANH DƯƠNG chuẩn ảnh thẻ (#0057B7).
- Màu bệt (flat color), không gradient.`;
  } else if (bgType === BackgroundType.GRAY) {
    prompt += `- Thay thế bằng nền XÁM TRUNG TÍNH sáng (#E5E7EB).
- Phù hợp ảnh hồ sơ chuyên nghiệp.`;
  } else {
    prompt += `- Giữ nguyên nền gốc, chỉ làm sạch nhiễu hạt (denoise) nếu có.`;
  }

  prompt += `\n\nBƯỚC 2: XỬ LÝ TRANG PHỤC (CLOTHING)\n`;

  // Clothing Logic
  if (clothingPrompt) {
    prompt += `- Thay trang phục hiện tại thành: "${clothingPrompt}".
- Yêu cầu: Khớp nối phần cổ và vai hoàn toàn tự nhiên với đầu gốc.
- Đổ bóng trang phục phù hợp với hướng sáng trên khuôn mặt.
- Phong cách: Nghiêm túc, lịch sự, chuẩn ảnh thẻ.`;
  } else {
    prompt += `- Giữ nguyên trang phục gốc.`;
  }

  prompt += `\n\nBƯỚC 3: XỬ LÝ LÀM ĐẸP (BEAUTY & RETOUCH)\n`;

  // Beauty Logic
  if (beautySettings.fixLighting) {
    prompt += `- Cân bằng ánh sáng: Làm sáng đều khuôn mặt, giảm bóng dầu, giảm vùng tối quá gắt trên mặt.\n`;
  }

  if (beautySettings.smoothSkin > 0) {
    prompt += `- Làm mịn da tự nhiên (Retouch): Giữ lại kết cấu da (skin texture), lỗ chân lông. KHÔNG làm da mịn như nhựa (plastic look).\n`;
  }

  if (beautySettings.removeBlemishes) {
    prompt += `- Xóa mụn, vết thâm tạm thời, vết mẩn đỏ. LƯU Ý: GIỮ NGUYÊN NỐT RUỒI VÀ SẸO LỒI.\n`;
  }

  if (beautySettings.lightMakeup) {
    prompt += `- Trang điểm rất nhẹ (No-makeup makeup look): Làm tươi tắn môi nhẹ, giảm quầng thâm mắt. Không kẻ mắt đậm.\n`;
  }

  if (beautySettings.fillHair) {
    prompt += `- Xử lý tóc: Làm đầy các vùng tóc thưa ở đỉnh đầu hoặc mái nếu cần thiết, nhưng giữ nguyên kiểu tóc gốc.\n`;
  }

  prompt += `
=========================================
ĐỊNH DẠNG ĐẦU RA
=========================================
- Chỉ trả về hình ảnh (Image only).
- Tỉ lệ khung hình: Giữ nguyên hoặc crop nhẹ chuẩn 4:6.
- Chất lượng: Cao nhất, sắc nét.
`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: cleanBase64
            }
          },
          {
            text: prompt
          }
        ]
      }
    });

    const parts = response.candidates?.[0]?.content?.parts;
    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
          return `data:image/jpeg;base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("Không nhận được dữ liệu ảnh từ Gemini.");

  } catch (error) {
    console.error("Gemini processing error:", error);
    throw error;
  }
};

