            <span className="text-brand-600">✨</span> Chỉnh sửa Ảnh
          </h2>
          <p className="text-xs text-gray-400 mt-1">Sử dụng AI để xử lý sinh trắc học</p>
        </div>

        {/* TAB NAVIGATION */}
        <div className="flex border-b border-gray-200 bg-gray-50">
          <button 
            onClick={() => setActiveTab('background')}
            className={`flex-1 py-3 text-sm font-bold transition-all border-b-2 ${activeTab === 'background' ? 'border-brand-500 text-brand-600 bg-white' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
          >
            Phông nền
          </button>
          <button 
            onClick={() => setActiveTab('beauty')}
            className={`flex-1 py-3 text-sm font-bold transition-all border-b-2 ${activeTab === 'beauty' ? 'border-brand-500 text-brand-600 bg-white' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
          >
            Làm đẹp
          </button>
          <button 
            onClick={() => setActiveTab('clothing')}
            className={`flex-1 py-3 text-sm font-bold transition-all border-b-2 ${activeTab === 'clothing' ? 'border-brand-500 text-brand-600 bg-white' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
