        {/* SCROLLABLE CONTENT */}
        <div className="flex-1 overflow-y-auto p-5 bg-white">

          {/* --- BACKGROUND TAB --- */}
          {activeTab === 'background' && (
            <div className="space-y-6">
              <div className="grid grid-cols-2 gap-3">
                <button 
                  onClick={() => handleBgChange(BackgroundType.WHITE)}
                  className={`p-4 rounded-xl border-2 flex flex-col items-center gap-2 transition-all ${settings.background === BackgroundType.WHITE ? 'border-brand-500 bg-brand-50 shadow-sm' : 'border-gray-100 hover:bg-gray-50'}`}
                >
