import React, { useState } from 'react';
import StartScreen from './StartScreen';
import CameraCapture from './CameraCapture';
import ImageEditor from './ImageEditor';
import PrintPreview from './PrintPreview';
import { AppStep, BackgroundType, PhotoSettings, PhotoSize, SavedPhoto } from '../types';

interface PhotoBoothProps {
  onSaveToGallery?: () => void;
  initialPhoto?: SavedPhoto | null; // Allow loading from gallery
}

const PhotoBooth: React.FC<PhotoBoothProps> = ({ onSaveToGallery, initialPhoto }) => {
  // If loading from gallery, skip config and capture, go to print
  const [step, setStep] = useState<AppStep>(initialPhoto ? AppStep.PRINT : AppStep.CONFIG);

  // Data State
  const [capturedImage, setCapturedImage] = useState<string>(initialPhoto ? initialPhoto.dataUrl : '');
  const [processedImage, setProcessedImage] = useState<string>(initialPhoto ? initialPhoto.dataUrl : '');

  // Settings State
  const [settings, setSettings] = useState<PhotoSettings>(initialPhoto ? initialPhoto.settings : {
    size: PhotoSize.SIZE_4X6, // Default
    background: BackgroundType.WHITE,
    brightness: 100,
    contrast: 100,
    smoothness: 0,
    clothingPrompt: undefined,
    beauty: {
      smoothSkin: 0,
      removeBlemishes: false,
      lightMakeup: false,
      fillHair: false,
      fixLighting: true // Default on for better results
    },
    printQuantity: 4
  });

  const handleStartConfig = (config: { size: PhotoSize; background: BackgroundType; quantity: number }) => {
    setSettings({
      ...settings,
      size: config.size,
      background: config.background,
      printQuantity: config.quantity
    });
    setStep(AppStep.CAPTURE);
  };

  const handleCapture = (imageSrc: string) => {
    setCapturedImage(imageSrc);
    setStep(AppStep.EDIT);
  };

  const handleProcessedImage = (img: string) => {
    setProcessedImage(img);
  };

  const resetFlow = () => {
    setCapturedImage('');
    setProcessedImage('');
    // Go back to start screen to allow choosing new customer type
    setStep(AppStep.CONFIG); 
  };

  const handleRetake = () => {
    setCapturedImage('');
    setStep(AppStep.CAPTURE);
  };

  return (
    <div className="h-full w-full">
      {step === AppStep.CONFIG && (
        <StartScreen onStart={handleStartConfig} />
      )}

      {step === AppStep.CAPTURE && (
        <CameraCapture 
          onCapture={handleCapture}
          selectedSize={settings.size}
          // In this flow, we don't usually change size during capture anymore, but we keep the handler if needed
          onSizeChange={(s) => setSettings({...settings, size: s})}
        />
      )}

      {step === AppStep.EDIT && (
        <ImageEditor 
          originalImage={capturedImage}
          settings={settings}
          onUpdateSettings={setSettings}
          onProcessedImage={handleProcessedImage}
          onNext={() => setStep(AppStep.PRINT)}
          onRetake={handleRetake}
        />
      )}

      {step === AppStep.PRINT && (
        <PrintPreview 
          processedImage={processedImage}
          size={settings.size}
          settings={settings}
          onBack={() => setStep(AppStep.EDIT)}
          onNew={resetFlow}
          onSaved={onSaveToGallery}
        />
      )}
    </div>
  );
};

export default PhotoBooth;

import { GoogleGenAI } from "@google/genai";
import { BackgroundType, BeautySettings, PhotoSize } from "../types";

const API_KEY = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey: API_KEY });

/**
 * Processes the ID photo with strict biometric preservation rules.
 */
export const processIDPhoto = async (
  imageBase64: string, 
  bgType: BackgroundType, 
  clothingPrompt: string | undefined,
  beautySettings: BeautySettings,
  size: PhotoSize
): Promise<string> => {
  if (!API_KEY) {
    throw new Error("API Key chưa được cấu hình.");
  }

  const cleanBase64 = imageBase64.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  // Determine specific cropping rules based on size
  let croppingRule = "";
  if (size === PhotoSize.SIZE_5X5) {
    croppingRule = `
- CROP & BỐ CỤC: Cắt ảnh theo tỉ lệ 1:1 (Vuông).
- KHUÔN MẶT: Phải chiếm từ 50% đến 69% tổng chiều cao ảnh (tính từ đỉnh đầu đến cằm).
- MẮT: Phải nằm ở khoảng 56% đến 69% chiều cao ảnh tính từ cạnh dưới lên.
- Căn giữa khuôn mặt theo trục dọc.`;
  } else {
    // 3x4 or 4x6 (Standard ID)
    croppingRule = `
- CROP & BỐ CỤC: Cắt ảnh theo tỉ lệ 4:6 (hoặc 2:3).
- KHUÔN MẶT: Phải chiếm từ 70% đến 80% tổng chiều cao ảnh.
- KHOẢNG CÁCH: Chừa một khoảng trống nhỏ phía trên đỉnh đầu (khoảng 10% chiều cao ảnh).
- VAI: Lấy đủ phần vai cân đối hai bên.
- Căn giữa khuôn mặt tuyệt đối.`;
  }

  // Constructing a structured prompt
  let prompt = `ROLE: Hệ thống AI xử lý ảnh sinh trắc học chuyên nghiệp (Passport/Visa/ID).
INPUT: Ảnh chân dung người (có thể chưa đúng khung).
OUTPUT: Ảnh đã xử lý hoàn thiện, CROP ĐÚNG TỶ LỆ, tách nền và chỉnh sửa.

=========================================
QUY TẮC BẤT DI BẤT DỊCH
=========================================
1. KHÔNG thay đổi cấu trúc xương mặt, mắt, mũi, miệng.
2. KHÔNG xóa nốt ruồi đặc trưng.
3. KHÔNG làm biến dạng (warping).
4. Giữ nguyên hướng nhìn.

=========================================
YÊU CẦU XỬ LÝ (QUAN TRỌNG NHẤT LÀ BƯỚC 1)
=========================================

BƯỚC 1: BỐ CỤC & TỶ LỆ (CRITICAL)
${croppingRule}
Nếu ảnh gốc quá rộng, hãy crop chặt vào khuôn mặt theo tỷ lệ trên. Nếu ảnh gốc thiếu nền, hãy tự động mở rộng nền (outpaint) để đạt tỷ lệ chuẩn.

BƯỚC 2: XỬ LÝ PHÔNG NỀN
`;

  // Background Logic
  if (bgType === BackgroundType.WHITE) {
    prompt += `- Tách nền và thay bằng MÀU TRẮNG TUYỆT ĐỐI (#FFFFFF). Không bóng đổ.`;
  } else if (bgType === BackgroundType.BLUE) {
    prompt += `- Tách nền và thay bằng XANH DƯƠNG chuẩn ảnh thẻ (#0057B7).`;
  } else if (bgType === BackgroundType.GRAY) {
    prompt += `- Thay bằng nền XÁM TRUNG TÍNH (#E5E7EB).`;
  } else {
    prompt += `- Giữ nguyên nền gốc (chỉ làm sạch nhiễu).`;
  }

  prompt += `\n\nBƯỚC 3: TRANG PHỤC\n`;
  if (clothingPrompt) {
    prompt += `- Thay trang phục thành: "${clothingPrompt}". Khớp nối cổ tự nhiên. Phong cách lịch sự.`;
  } else {
    prompt += `- Giữ nguyên trang phục gốc.`;
  }

  prompt += `\n\nBƯỚC 4: LÀM ĐẸP (RETOUCH)\n`;
  if (beautySettings.fixLighting) prompt += `- Cân bằng ánh sáng, giảm bóng dầu.\n`;
  if (beautySettings.smoothSkin > 0) prompt += `- Làm mịn da tự nhiên, giữ kết cấu da.\n`;
  if (beautySettings.removeBlemishes) prompt += `- Xóa mụn/vết thâm tạm thời.\n`;
  if (beautySettings.lightMakeup) prompt += `- Makeup nhẹ nhàng, tươi tắn.\n`;
  if (beautySettings.fillHair) prompt += `- Làm đầy tóc thưa (nếu có).\n`;

  prompt += `
=========================================
ĐỊNH DẠNG ĐẦU RA
=========================================
- Chỉ trả về hình ảnh JPEG chất lượng cao.
- Đảm bảo tỷ lệ khung hình đầu ra đúng như yêu cầu ở Bước 1.
`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: cleanBase64
            }
          },
          {
            text: prompt
          }
        ]
      }
    });

    const parts = response.candidates?.[0]?.content?.parts;
    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
          return `data:image/jpeg;base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("Không nhận được dữ liệu ảnh từ Gemini.");

  } catch (error) {
    console.error("Gemini processing error:", error);
    throw error;
  }
};

import React, { useState } from 'react';
import { BackgroundType, PhotoSettings, PhotoSize } from '../types';
