type EditorTab = 'background' | 'beauty' | 'clothing';

const ImageEditor: React.FC<ImageEditorProps> = ({ 
  originalImage, 
  settings, 
  onUpdateSettings,
  onProcessedImage,
  onNext,
  onRetake
}) => {
  const [displayImage, setDisplayImage] = useState<string>(originalImage);
  const [isProcessing, setIsProcessing] = useState(false);
  const [activeTab, setActiveTab] = useState<EditorTab>('background');
  const [showGrid, setShowGrid] = useState(true); // Default show grid to check ratio

  // Local state for UI controls before applying AI
  const [clothingInput, setClothingInput] = useState('');
  const [genderTab, setGenderTab] = useState<'male' | 'female'>('male');
  const [apiError, setApiError] = useState('');

  // Apply visual CSS filters instantly (Brightness/Contrast only)
  const filterStyle = {
    filter: `brightness(${settings.brightness}%) contrast(${settings.contrast}%)`,
  };

  // --- CORE AI HANDLER ---
  const triggerAI = async (
    overrideBg?: BackgroundType, 
    overrideClothing?: string,
    overrideBeauty?: any
  ) => {
    setIsProcessing(true);
    setApiError('');

    // Determine effective settings
    const effBg = overrideBg !== undefined ? overrideBg : settings.background;
    const effClothing = overrideClothing !== undefined ? overrideClothing : settings.clothingPrompt;
    const effBeauty = overrideBeauty !== undefined ? overrideBeauty : settings.beauty;

    try {
      // Pass the settings.size to the API so it knows how to crop!
      const result = await processIDPhoto(originalImage, effBg, effClothing, effBeauty, settings.size);

      setDisplayImage(result);
      onUpdateSettings({ 
        ...settings, 
        background: effBg, 
        clothingPrompt: effClothing,
        beauty: effBeauty 
      });
    } catch (err: any) {
      setApiError(err.message || "Lỗi xử lý AI. Vui lòng thử lại.");
    } finally {
      setIsProcessing(false);
    }
  };

  // --- HANDLERS ---
  const handleBgChange = (bg: BackgroundType) => {
    triggerAI(bg, undefined, undefined);
  };

  const handleClothingClick = (prompt: string) => {
    setClothingInput(prompt);
    triggerAI(undefined, prompt, undefined);
  };

  const handleManualClothing = () => {
    if (!clothingInput.trim()) return;
    triggerAI(undefined, clothingInput, undefined);
  };

  const handleBeautyToggle = (key: keyof typeof settings.beauty) => {
    const newBeauty = { 
      ...settings.beauty, 
      [key]: !settings.beauty[key as keyof typeof settings.beauty] 
    };
    // For toggles, we trigger AI immediately for better UX
    triggerAI(undefined, undefined, newBeauty);
  };

  const handleSmoothnessChange = (val: number) => {
    onUpdateSettings({
      ...settings,
      beauty: { ...settings.beauty, smoothSkin: val }
    });
  };

  // Finish: Draw to canvas to bake in CSS filters
  const handleFinish = () => {
    const canvas = document.createElement('canvas');
    const img = new Image();
    img.src = displayImage;
    img.crossOrigin = "anonymous";
    img.onload = () => {
      // Logic for Aspect Ratio
      let aspectRatio;
      if (settings.size === PhotoSize.SIZE_5X5) {
        aspectRatio = 1;
      } else {
        aspectRatio = settings.size === PhotoSize.SIZE_3X4 ? 3/4 : 4/6;
      }

      let sourceW = img.width;
      let sourceH = img.height;
      let targetW, targetH;
      let offsetX = 0;
      let offsetY = 0;

      if (sourceW / sourceH > aspectRatio) {
        targetH = sourceH;
        targetW = sourceH * aspectRatio;
        offsetX = (sourceW - targetW) / 2;
      } else {
        targetW = sourceW;
        targetH = sourceW / aspectRatio;
        offsetY = (sourceH - targetH) / 2;
      }

      canvas.width = targetW;
      canvas.height = targetH;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        // Apply CSS filters (Brightness/Contrast)
        ctx.filter = `brightness(${settings.brightness}%) contrast(${settings.contrast}%)`;

        // Draw image centered
        ctx.drawImage(img, offsetX, offsetY, targetW, targetH, 0, 0, targetW, targetH);
        onProcessedImage(canvas.toDataURL('image/png'));
        onNext();
      }
    };
  };

  return (
    <div className="flex flex-col md:flex-row h-full w-full bg-gray-100 overflow-hidden font-sans">

      {/* LEFT: Sidebar / Controls */}
      <div className="w-full md:w-[400px] bg-white shadow-xl z-20 flex flex-col h-full border-r border-gray-200">

        {/* Header */}
        <div className="p-5 border-b border-gray-100 bg-white">
          <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2">
            <span className="text-brand-600">✨</span> Chỉnh sửa Ảnh
          </h2>
          <p className="text-xs text-gray-400 mt-1">Sử dụng AI để xử lý sinh trắc học</p>
        </div>

        {/* TAB NAVIGATION */}
        <div className="flex border-b border-gray-200 bg-gray-50">
          <button 
            onClick={() => setActiveTab('background')}
            className={`flex-1 py-3 text-sm font-bold transition-all border-b-2 ${activeTab === 'background' ? 'border-brand-500 text-brand-600 bg-white' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
          >
            Phông nền
          </button>
          <button 
            onClick={() => setActiveTab('beauty')}
