          />

          {/* BIOMETRIC CHECK OVERLAY */}
          {showGrid && (
             <div className="absolute inset-0 pointer-events-none z-20 opacity-60">
                {settings.size === PhotoSize.SIZE_5X5 ? (
                  // Overlay for 5x5 Visa
                  <svg viewBox="0 0 100 100" className="w-full h-full" preserveAspectRatio="none">
                     <line x1="50" y1="0" x2="50" y2="100" stroke="rgba(255,0,0,0.5)" strokeWidth="0.5" strokeDasharray="2,2"/>
                     {/* Eye Zone (56% - 69% from bottom => 31% - 44% from top) */}
                     <rect x="0" y="31" width="100" height="13" fill="rgba(0,255,0,0.1)" stroke="green" strokeWidth="0.2"/>
