                     {/* Face Height 50-69% */}
                     <line x1="0" y1="15" x2="100" y2="15" stroke="blue" strokeWidth="0.3" strokeDasharray="2,2" />
                     <text x="2" y="14" fontSize="2" fill="blue">Đỉnh đầu (Max)</text>
                  </svg>
                ) : (
                  // Overlay for 3x4 / 4x6
                   <svg viewBox="0 0 100 100" className="w-full h-full" preserveAspectRatio="none">
                     <line x1="50" y1="0" x2="50" y2="100" stroke="rgba(255,0,0,0.5)" strokeWidth="0.5" strokeDasharray="2,2"/>
                     {/* Head Top ~10-12% */}
                     <line x1="20" y1="12" x2="80" y2="12" stroke="red" strokeWidth="0.3" />
                     {/* Chin ~82-85% */}
                     <line x1="30" y1="85" x2="70" y2="85" stroke="red" strokeWidth="0.3" />
                     {/* Eye Line ~45% */}
                     <line x1="0" y1="45" x2="100" y2="45" stroke="green" strokeWidth="0.5" strokeDasharray="4,2"/>
                  </svg>
                )}
             </div>
          )}

          {/* Toggle Grid Button */}
          <button
             onClick={() => setShowGrid(!showGrid)}
             className="absolute top-4 right-4 bg-black/60 text-white p-2 rounded-lg hover:bg-black/80 z-40"
             title="Bật/Tắt Lưới tỷ lệ"
          >
             {showGrid ? (
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 3h18v18H3V3zm6 0v18M15 3v18M3 9h18M3 15h18"></path></svg>
             ) : (
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z"></path></svg>
             )}
          </button>

          {/* Badge */}
          <div className="absolute top-4 left-4 bg-black/70 text-white px-3 py-1 rounded-full text-xs font-medium backdrop-blur-md z-40">
            {settings.size === PhotoSize.SIZE_5X5 ? '5x5 (Visa)' : settings.size}
