          {/* Compare Button (Hold to show original) */}
           <button 
            className="absolute bottom-4 right-4 bg-white/90 border border-gray-300 text-gray-700 px-4 py-2 rounded-full text-xs font-bold shadow hover:bg-white active:bg-brand-50 z-40"
