import { GoogleGenAI } from "@google/genai";
import { BackgroundType, BeautySettings, PhotoSize } from "../types";

const API_KEY = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey: API_KEY });

/**
 * Processes the ID photo with strict biometric preservation rules.
 * CRITICAL: NO CROPPING OR RESIZING ALLOWED IN THIS STEP.
 */
export const processIDPhoto = async (
  imageBase64: string, 
  bgType: BackgroundType, 
  clothingPrompt: string | undefined,
  beautySettings: BeautySettings,
  size: PhotoSize
): Promise<string> => {
  if (!API_KEY) {
    throw new Error("API Key chưa được cấu hình.");
  }

  const cleanBase64 = imageBase64.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  // Constructing a structured prompt focused on IN-PLACE EDITING
  let prompt = `ROLE: Hệ thống xử lý ảnh thẻ chuyên dụng (Pixel-perfect ID Photo Editor).
INPUT: Ảnh chân dung đã được CROP ĐÚNG TỶ LỆ (${size}).
OUTPUT: Ảnh đầu ra giữ nguyên kích thước, giữ nguyên vị trí khuôn mặt.

================================================================
NGUYÊN TẮC BẤT BIẾN (KHÓA CỨNG – ƯU TIÊN CAO NHẤT)
================================================================
1. KHÔNG ĐƯỢC CROP LẠI ẢNH. Giữ nguyên khung hình hiện tại.
2. KHÔNG ĐƯỢC THAY ĐỔI VỊ TRÍ KHUÔN MẶT (dù chỉ 1 pixel).
3. KHÔNG ĐƯỢC BIẾN DẠNG (WARP) CẤU TRÚC XƯƠNG MẶT.
4. KHÔNG ĐƯỢC PHÓNG TO / THU NHỎ CHỦ THỂ.
5. Mục tiêu: Chỉ thay đổi pixel của Nền và Quần Áo, giữ nguyên pixel của khuôn mặt (trừ khi làm mịn da).

================================================================
YÊU CẦU XỬ LÝ (THEO THỨ TỰ ƯU TIÊN)
================================================================

1. XỬ LÝ PHÔNG NỀN (BACKGROUND):
`;

  // Background Logic
  if (bgType === BackgroundType.WHITE) {
    prompt += `- Thay nền hiện tại bằng MÀU TRẮNG TUYỆT ĐỐI (#FFFFFF).
- Tách tóc chi tiết, không làm lẹm tóc.
- Không tạo bóng đổ giả (Drop shadow).`;
  } else if (bgType === BackgroundType.BLUE) {
    prompt += `- Thay nền hiện tại bằng XANH DƯƠNG CHUẨN ẢNH THẺ (#0057B7).
- Màu bệt (Flat color), không gradient.`;
  } else if (bgType === BackgroundType.GRAY) {
    prompt += `- Thay nền bằng XÁM TRUNG TÍNH (#E5E7EB).`;
  } else {
    prompt += `- GIỮ NGUYÊN NỀN GỐC. Chỉ làm sạch nhiễu hạt (Denoise) nền nếu cần.`;
  }

  prompt += `\n\n2. XỬ LÝ TRANG PHỤC (CLOTHING):\n`;
  if (clothingPrompt) {
    prompt += `- Thay trang phục thành: "${clothingPrompt}".
- KHỚP NỐI: Giữ nguyên phần cổ và đầu của chủ thể. Chỉ thay thế phần áo từ vai trở xuống.
- ÁNH SÁNG: Đổ bóng lên áo mới phải khớp với hướng sáng trên khuôn mặt.
- PHONG CÁCH: Lịch sự, phẳng phiu, chuẩn ảnh hành chính.`;
  } else {
    prompt += `- GIỮ NGUYÊN TRANG PHỤC GỐC.`;
  }

  prompt += `\n\n3. LÀM ĐẸP (RETOUCH - NHẸ NHÀNG):\n`;
  // Beauty Logic - Focus on "Natural" and "Structure preservation"
  if (beautySettings.fixLighting) prompt += `- Cân bằng ánh sáng trên mặt (giảm vùng cháy sáng/quá tối), nhưng giữ nguyên khối mặt (3D structure).\n`;
  if (beautySettings.smoothSkin > 0) prompt += `- Làm mịn da nhẹ (Retouching), GIỮ LẠI KẾT CẤU DA (Texture). Không làm da bị mờ (Blur).\n`;
  if (beautySettings.removeBlemishes) prompt += `- Chỉ xóa mụn, vết thâm đỏ tạm thời. KHÔNG XÓA NỐT RUỒI, KHÔNG XÓA SẸO.\n`;
  if (beautySettings.lightMakeup) prompt += `- Makeup vô hình (Invisible makeup): Môi tươi tắn hơn một chút, giảm thâm mắt. Không thay đổi hình dáng mắt/môi.\n`;
  if (beautySettings.fillHair) prompt += `- Bù tóc nhẹ ở phần đỉnh hoặc mái nếu bị lẹm do ánh sáng, nhưng giữ nguyên kiểu tóc.\n`;

  prompt += `
================================================================
ĐỊNH DẠNG ĐẦU RA
================================================================
- Trả về ảnh JPEG chất lượng cao nhất.
- Kích thước ảnh đầu ra PHẢI TRÙNG KHỚP hoàn toàn với ảnh đầu vào.
`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image', // Using the fast/efficient image model
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: cleanBase64
            }
          },
          {
            text: prompt
          }
        ]
      }
    });

    const parts = response.candidates?.[0]?.content?.parts;
    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
          return `data:image/jpeg;base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("Không nhận được dữ liệu ảnh từ Gemini.");

  } catch (error) {
    console.error("Gemini processing error:", error);
    throw error;
  }
};

import React, { useRef, useState, useEffect, useCallback } from 'react';
import { PhotoSize } from '../types';

interface CameraCaptureProps {
  onCapture: (imageSrc: string) => void;
  selectedSize: PhotoSize;
  onSizeChange: (size: PhotoSize) => void;
}

// Mock AI States for UX Demonstration
type ValidationStatus = 'scanning' | 'detecting' | 'error' | 'valid';

const CameraCapture: React.FC<CameraCaptureProps> = ({ onCapture, selectedSize, onSizeChange }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string>('');
  const [countdown, setCountdown] = useState<number | null>(null);

  const [devices, setDevices] = useState<MediaDeviceInfo[]>([]);
  const [selectedDeviceId, setSelectedDeviceId] = useState<string>('');

  // AI Validation State
  const [validationStatus, setValidationStatus] = useState<ValidationStatus>('scanning');
  const [feedbackMessage, setFeedbackMessage] = useState<string>('Đang tìm khuôn mặt...');

  // Simulation Loop for "AI Detection" UX
  useEffect(() => {
    // Reset status when size changes
    setValidationStatus('scanning');
    setFeedbackMessage('Đang quét sinh trắc học...');

    const timers: ReturnType<typeof setTimeout>[] = [];

    // Simulate flow: Scanning -> Detecting -> Analysis -> Ready
    timers.push(setTimeout(() => {
      setValidationStatus('detecting');
      setFeedbackMessage('Đang phân tích tỷ lệ...');
    }, 800));

    timers.push(setTimeout(() => {
      // Simulate a random check (usually valid for demo purposes)
      setValidationStatus('valid');
      setFeedbackMessage('ĐẠT CHUẨN');
    }, 2000));

    return () => timers.forEach(clearTimeout);
  }, [selectedSize]);

  useEffect(() => {
    getDevices();
    startCamera();
    return () => stopCamera();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (selectedDeviceId) startCamera(selectedDeviceId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedDeviceId]);

  const getDevices = async () => {
    try {
      const allDevices = await navigator.mediaDevices.enumerateDevices();
      const videoDevices = allDevices.filter(device => device.kind === 'videoinput');
      setDevices(videoDevices);
      const canon = videoDevices.find(d => d.label.toLowerCase().includes('canon') || d.label.toLowerCase().includes('eos'));
      if (canon) setSelectedDeviceId(canon.deviceId);
    } catch (err) {
      console.error("Error enumerating devices", err);
    }
  };

  const startCamera = async (deviceId?: string) => {
    stopCamera();
    try {
      const constraints: MediaStreamConstraints = {
        video: {
          deviceId: deviceId ? { exact: deviceId } : undefined,
          width: { ideal: 1920 }, // High resolution for quality crop
          height: { ideal: 1080 },
        },
        audio: false
      };
      const mediaStream = await navigator.mediaDevices.getUserMedia(constraints);
      setStream(mediaStream);
      if (videoRef.current) videoRef.current.srcObject = mediaStream;
      setError('');
    } catch (err) {
      setError('Không thể truy cập camera. Kiểm tra kết nối.');
    }
  };

  const stopCamera = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
    }
  };

  const captureFrame = useCallback(() => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      const context = canvas.getContext('2d');

      if (context && video.videoWidth > 0 && video.videoHeight > 0) {
        // We need to crop the video feed to match the aspect ratio of the selected size
        // 5x5 = 1:1 ratio
        // 4x6 = 2:3 ratio
        // 3x4 = 3:4 ratio

        let targetRatio = 2/3; // Default 4x6
        if (selectedSize === PhotoSize.SIZE_5X5) targetRatio = 1;
        if (selectedSize === PhotoSize.SIZE_3X4) targetRatio = 3/4;

        const videoRatio = video.videoWidth / video.videoHeight;

        let sourceW, sourceH, startX, startY;

        if (videoRatio > targetRatio) {
          // Video is wider than target
          sourceH = video.videoHeight;
          sourceW = sourceH * targetRatio;
          startX = (video.videoWidth - sourceW) / 2;
          startY = 0;
        } else {
          // Video is taller than target (unlikely for landscape webcam, but possible)
          sourceW = video.videoWidth;
          sourceH = sourceW / targetRatio;
          startX = 0;
          startY = (video.videoHeight - sourceH) / 2;
        }

        canvas.width = sourceW;
        canvas.height = sourceH;

        // Mirror effect for selfie camera
        context.translate(canvas.width, 0);
        context.scale(-1, 1); 

        context.drawImage(video, startX, startY, sourceW, sourceH, 0, 0, canvas.width, canvas.height);

        const dataUrl = canvas.toDataURL('image/jpeg', 1.0); // High quality JPEG
        onCapture(dataUrl);
      }
    }
  }, [onCapture, selectedSize]);

  useEffect(() => {
    if (countdown === null) return;

    if (countdown > 0) {
      const timer = setTimeout(() => {
        setCountdown(countdown - 1);
      }, 1000);
      return () => clearTimeout(timer);
    } else if (countdown === 0) {
      captureFrame();
      setCountdown(null);
    }
  }, [countdown, captureFrame]);

  const handleCaptureClick = () => {
    if (validationStatus === 'valid') {
      setCountdown(3);
    }
  };

  const isUSVisa = selectedSize === PhotoSize.SIZE_5X5;
  const is3x4 = selectedSize === PhotoSize.SIZE_3X4;

  const getStatusColor = () => {
    switch (validationStatus) {
      case 'valid': return 'border-green-500 shadow-[0_0_20px_rgba(34,197,94,0.6)]';
      case 'error': return 'border-red-500 shadow-[0_0_20px_rgba(239,68,68,0.6)]';
      default: return 'border-blue-400 shadow-[0_0_20px_rgba(96,165,250,0.4)]';
    }
  };

  return (
    <div className="flex flex-col items-center justify-center h-full w-full bg-gray-900 relative select-none">

      {/* Top Bar */}
      <div className="absolute top-0 left-0 right-0 z-50 p-4 flex justify-between items-start bg-gradient-to-b from-black/80 to-transparent pb-12">
        <select 
          value={selectedDeviceId}
          onChange={(e) => setSelectedDeviceId(e.target.value)}
          className="bg-black/50 text-white text-xs border border-gray-600 rounded px-3 py-1.5 outline-none backdrop-blur-md pointer-events-auto"
        >
          <option value="">-- Chọn Camera --</option>
          {devices.map((device, idx) => (
            <option key={device.deviceId || idx} value={device.deviceId}>
              {device.label || `Camera ${idx + 1}`}
            </option>
          ))}
        </select>

        {/* Realtime Feedback Status */}
        <div className={`
          px-4 py-2 rounded-lg backdrop-blur-md border flex items-center gap-2 transition-all duration-300
          ${validationStatus === 'valid' ? 'bg-green-500/20 border-green-500 text-green-100' : 
            validationStatus === 'error' ? 'bg-red-500/20 border-red-500 text-red-100' : 
            'bg-blue-500/20 border-blue-400 text-blue-100'}
        `}>
          {validationStatus === 'scanning' && <div className="animate-spin w-3 h-3 border-2 border-current border-t-transparent rounded-full" />}
          {validationStatus === 'valid' && <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg>}
          <span className="font-bold text-sm tracking-wide uppercase">{feedbackMessage}</span>
        </div>
      </div>

      {error && <div className="absolute z-50 bg-red-600 text-white p-4 rounded-lg shadow-xl font-bold animate-pulse">{error}</div>}

      {/* Camera Feed with Aspect Ratio Crop Preview */}
      <div 
        className={`relative transition-all duration-300 bg-black rounded-lg overflow-hidden flex items-center justify-center border-2 border-gray-800
          ${isUSVisa ? 'aspect-square h-[80vh]' : is3x4 ? 'aspect-[3/4] h-[80vh]' : 'aspect-[2/3] h-[80vh]'}
        `}
      >
        <video
          ref={videoRef}
          autoPlay
          playsInline
          className="absolute inset-0 w-full h-full object-cover transform -scale-x-100" 
        />

        {/* =============================================
            STRICT BIOMETRIC GUIDES (SVG)
           ============================================= */}
        <div 
           className={`relative z-10 w-full h-full border-2 transition-all duration-500 ${getStatusColor()}`}
        >
          {validationStatus === 'scanning' && (
            <div className="absolute top-0 left-0 w-full h-1 bg-blue-400/80 shadow-[0_0_15px_rgba(96,165,250,1)] animate-[scan_2s_ease-in-out_infinite]" />
          )}

          {isUSVisa ? (
            // --- VISA MỸ (5x5) STRICT GUIDE ---
            <svg viewBox="0 0 100 100" className="absolute inset-0 w-full h-full opacity-80 pointer-events-none">
              <line x1="50" y1="0" x2="50" y2="100" stroke="rgba(255,255,255,0.4)" strokeWidth="0.2" strokeDasharray="2,2" />

              {/* Eye Zone: 56% - 69% from bottom => 31% - 44% from top */}
              <rect x="0" y="31" width="100" height="13" fill="rgba(0, 255, 0, 0.1)" stroke="none" />
              <line x1="0" y1="31" x2="100" y2="31" stroke="#00ff00" strokeWidth="0.3" strokeDasharray="4,2" />
              <line x1="0" y1="44" x2="100" y2="44" stroke="#00ff00" strokeWidth="0.3" strokeDasharray="4,2" />
              <text x="5" y="30" fill="#00ff00" fontSize="2.5">MẮT (Max)</text>
              <text x="5" y="47" fill="#00ff00" fontSize="2.5">MẮT (Min)</text>

              {/* Head Height: 50% - 69% (Height from top of head to chin) */}
              {/* This is complex to visualize perfectly, so we show an IDEAL OVAL */}
              <ellipse cx="50" cy="50" rx="28" ry="35" fill="none" stroke="rgba(255,255,255,0.7)" strokeWidth="0.5" strokeDasharray="6,4" />

              <text x="50" y="95" fill="white" fontSize="3" textAnchor="middle" fontWeight="bold">VISA MỸ 5x5</text>
            </svg>
          ) : (
             // --- 4x6 & 3x4 GUIDE (STANDARD) ---
             // Face takes ~75% area. Eyes ~2/3 from bottom.
            <svg viewBox="0 0 100 100" className="absolute inset-0 w-full h-full opacity-80 pointer-events-none">
              <line x1="50" y1="0" x2="50" y2="100" stroke="rgba(255,255,255,0.4)" strokeWidth="0.2" strokeDasharray="2,2" />

              {/* Head Top Margin: ~10-12% space at top */}
              <line x1="30" y1="12" x2="70" y2="12" stroke="red" strokeWidth="0.5" />
              <text x="50" y="10" fill="red" fontSize="2.5" textAnchor="middle">ĐỈNH ĐẦU</text>

              {/* Chin Line: ~85% down */}
              <line x1="35" y1="85" x2="65" y2="85" stroke="red" strokeWidth="0.5" />
              <text x="50" y="89" fill="red" fontSize="2.5" textAnchor="middle">CẰM</text>

              {/* Eye Line: ~45% from top (approx 2/3 from bottom of face) */}
              <line x1="20" y1="45" x2="80" y2="45" stroke="#00ff00" strokeWidth="0.5" strokeDasharray="4,4" />
              <text x="82" y="46" fill="#00ff00" fontSize="2.5" fontWeight="bold">MẮT</text>

              {/* Face Contour Hint */}
              <ellipse cx="50" cy="48" rx="24" ry="32" fill="none" stroke="rgba(255,255,255,0.5)" strokeWidth="0.5" strokeDasharray="2,2" />

              <text x="50" y="95" fill="white" fontSize="3" textAnchor="middle" fontWeight="bold">{is3x4 ? 'THẺ 3x4' : 'HỘ CHIẾU 4x6'}</text>
            </svg>
          )}

        </div>

        {/* Countdown Overlay */}
        {countdown !== null && (
          <div className="absolute inset-0 flex items-center justify-center bg-black/60 z-40 backdrop-blur-sm">
            <span className="text-[120px] font-bold text-white animate-ping">{countdown}</span>
          </div>
        )}
      </div>

      {/* Capture Controls */}
      <div className="absolute bottom-8 left-0 right-0 flex flex-col justify-end items-center gap-4 z-50 pointer-events-auto">
        <div className={`text-sm font-medium px-3 py-1 rounded bg-black/50 backdrop-blur ${validationStatus === 'valid' ? 'text-green-400' : 'text-gray-300'}`}>
           {validationStatus === 'valid' ? '✔ Giữ nguyên, chuẩn bị chụp' : 'Di chuyển khuôn mặt khớp khung xanh'}
        </div>

        <button
          onClick={handleCaptureClick}
          disabled={validationStatus !== 'valid' || countdown !== null}
          className={`
            w-20 h-20 rounded-full border-4 transition-all duration-300 flex items-center justify-center shadow-2xl
            ${validationStatus === 'valid' 
              ? 'bg-white border-gray-200 hover:border-brand-500 hover:scale-105 active:scale-95 cursor-pointer' 
              : 'bg-gray-600 border-gray-700 opacity-50 cursor-not-allowed'}
          `}
        >
           <div className={`w-16 h-16 rounded-full transition-all duration-300 ${validationStatus === 'valid' ? 'bg-brand-600' : 'bg-gray-500'}`}></div>
        </button>
      </div>

      <canvas ref={canvasRef} className="hidden" />

      <style>{`
        @keyframes scan {
          0% { top: 0%; opacity: 0; }
          10% { opacity: 1; }
          90% { opacity: 1; }
          100% { top: 100%; opacity: 0; }
        }
      `}</style>
    </div>
  );
};

