type EditorTab = 'background' | 'beauty' | 'clothing';

const ImageEditor: React.FC<ImageEditorProps> = ({ 
  originalImage, 
  settings, 
  onUpdateSettings,
  onProcessedImage,
  onNext,
  onRetake
}) => {
  const [processedUrl, setProcessedUrl] = useState<string>(originalImage);
  const [isProcessing, setIsProcessing] = useState(false);
  const [activeTab, setActiveTab] = useState<EditorTab>('background');

  // Before/After Slider State
  const [sliderPosition, setSliderPosition] = useState(50);
  const imageContainerRef = useRef<HTMLDivElement>(null);
  const isDraggingRef = useRef(false);

  // Local state for UI controls before applying AI
  const [clothingInput, setClothingInput] = useState('');
  const [genderTab, setGenderTab] = useState<'male' | 'female'>('male');
  const [apiError, setApiError] = useState('');

  // Initial trigger to process background if not original
  useEffect(() => {
    if (settings.background !== BackgroundType.ORIGINAL && processedUrl === originalImage) {
      triggerAI();
    }
  }, []); // Run once on mount

  // Apply visual CSS filters instantly (Brightness/Contrast only)
  // Note: These filters apply to BOTH Before and After images for fair comparison
  const filterStyle = {
    filter: `brightness(${settings.brightness}%) contrast(${settings.contrast}%)`,
  };

  // --- CORE AI HANDLER ---
  const triggerAI = async (
    overrideBg?: BackgroundType, 
    overrideClothing?: string,
    overrideBeauty?: any
  ) => {
    setIsProcessing(true);
    setApiError('');

    const effBg = overrideBg !== undefined ? overrideBg : settings.background;
    const effClothing = overrideClothing !== undefined ? overrideClothing : settings.clothingPrompt;
    const effBeauty = overrideBeauty !== undefined ? overrideBeauty : settings.beauty;

    try {
      // Logic: If everything is default, just show original
      const isDefault = effBg === BackgroundType.ORIGINAL && !effClothing && 
        Object.values(effBeauty).every(v => !v || v === 0);

      if (isDefault) {
        setProcessedUrl(originalImage);
      } else {
        const result = await processIDPhoto(originalImage, effBg, effClothing, effBeauty, settings.size);
        setProcessedUrl(result);
      }

      onUpdateSettings({ 
        ...settings, 
        background: effBg, 
        clothingPrompt: effClothing,
        beauty: effBeauty 
      });
    } catch (err: any) {
      setApiError(err.message || "Lỗi xử lý AI. Vui lòng thử lại.");
    } finally {
      setIsProcessing(false);
    }
  };

  // --- HANDLERS ---
  const handleBgChange = (bg: BackgroundType) => triggerAI(bg, undefined, undefined);
  const handleClothingClick = (prompt: string) => {
    setClothingInput(prompt);
    triggerAI(undefined, prompt, undefined);
  };
  const handleManualClothing = () => {
    if (clothingInput.trim()) triggerAI(undefined, clothingInput, undefined);
  };
  const handleBeautyToggle = (key: keyof typeof settings.beauty) => {
    const newBeauty = { ...settings.beauty, [key]: !settings.beauty[key as keyof typeof settings.beauty] };
    triggerAI(undefined, undefined, newBeauty);
  };
  const handleSmoothnessChange = (val: number) => {
    // Only update state, user must click Apply for heavy slider ops usually, 
    // but for smooth UX we can debounce or just update state for now.
    // Here we update state, then user can re-trigger if they want, or we can use onMouseUp.
    onUpdateSettings({ ...settings, beauty: { ...settings.beauty, smoothSkin: val } });
  };
  const handleSliderMouseUp = () => {
     triggerAI(); // Re-process when slider released
  };

  // Drag logic for Before/After slider
  const handleMouseMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isDraggingRef.current || !imageContainerRef.current) return;
    const rect = imageContainerRef.current.getBoundingClientRect();
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const x = Math.max(0, Math.min(clientX - rect.left, rect.width));
    setSliderPosition((x / rect.width) * 100);
  };

  // Finish: Draw to canvas to bake in CSS filters
  const handleFinish = () => {
    const canvas = document.createElement('canvas');
    const img = new Image();
    img.src = processedUrl;
    img.crossOrigin = "anonymous";
    img.onload = () => {
      canvas.width = img.width;
      canvas.height = img.height;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.filter = `brightness(${settings.brightness}%) contrast(${settings.contrast}%)`;
        ctx.drawImage(img, 0, 0);
        onProcessedImage(canvas.toDataURL('image/jpeg', 0.95));
        onNext();
      }
    };
  };

  return (
    <div className="flex flex-col md:flex-row h-full w-full bg-gray-100 overflow-hidden font-sans"
      onMouseMove={handleMouseMove}
      onTouchMove={handleMouseMove}
      onMouseUp={() => { isDraggingRef.current = false; }}
      onTouchEnd={() => { isDraggingRef.current = false; }}
    >

      {/* LEFT: Sidebar / Controls */}
      <div className="w-full md:w-[400px] bg-white shadow-xl z-20 flex flex-col h-full border-r border-gray-200">

        {/* Header */}
        <div className="p-5 border-b border-gray-100 bg-white">
          <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2">
            <span className="text-brand-600">✨</span> Chỉnh sửa Ảnh
          </h2>
          <p className="text-xs text-gray-400 mt-1">AI xử lý: Giữ nguyên sinh trắc học</p>
        </div>

        {/* TAB NAVIGATION */}
        <div className="flex border-b border-gray-200 bg-gray-50">
          <button onClick={() => setActiveTab('background')} className={`flex-1 py-3 text-sm font-bold border-b-2 ${activeTab === 'background' ? 'border-brand-500 text-brand-600 bg-white' : 'border-transparent text-gray-500 hover:text-gray-700'}`}>Phông nền</button>
          <button onClick={() => setActiveTab('beauty')} className={`flex-1 py-3 text-sm font-bold border-b-2 ${activeTab === 'beauty' ? 'border-brand-500 text-brand-600 bg-white' : 'border-transparent text-gray-500 hover:text-gray-700'}`}>Làm đẹp</button>
          <button onClick={() => setActiveTab('clothing')} className={`flex-1 py-3 text-sm font-bold border-b-2 ${activeTab === 'clothing' ? 'border-brand-500 text-brand-600 bg-white' : 'border-transparent text-gray-500 hover:text-gray-700'}`}>Trang phục</button>
        </div>

        {/* SCROLLABLE CONTENT */}
        <div className="flex-1 overflow-y-auto p-5 bg-white">

          {/* --- BACKGROUND TAB --- */}
          {activeTab === 'background' && (
            <div className="space-y-6">
              <div className="grid grid-cols-2 gap-3">
                <button onClick={() => handleBgChange(BackgroundType.WHITE)} className={`p-4 rounded-xl border-2 flex flex-col items-center gap-2 ${settings.background === BackgroundType.WHITE ? 'border-brand-500 bg-brand-50' : 'border-gray-100'}`}>
                  <div className="w-8 h-8 rounded-full bg-white border border-gray-200 shadow-inner"></div>
                  <span className="text-sm font-medium">Trắng (Visa/ID)</span>
                </button>
                <button onClick={() => handleBgChange(BackgroundType.BLUE)} className={`p-4 rounded-xl border-2 flex flex-col items-center gap-2 ${settings.background === BackgroundType.BLUE ? 'border-brand-500 bg-brand-50' : 'border-gray-100'}`}>
                  <div className="w-8 h-8 rounded-full bg-[#0057B7] shadow-inner"></div>
                  <span className="text-sm font-medium">Xanh (Hồ sơ)</span>
                </button>
                <button onClick={() => handleBgChange(BackgroundType.GRAY)} className={`p-4 rounded-xl border-2 flex flex-col items-center gap-2 ${settings.background === BackgroundType.GRAY ? 'border-brand-500 bg-brand-50' : 'border-gray-100'}`}>
                  <div className="w-8 h-8 rounded-full bg-gray-300 shadow-inner"></div>
                  <span className="text-sm font-medium">Xám (CV)</span>
                </button>
                <button onClick={() => handleBgChange(BackgroundType.ORIGINAL)} className={`p-4 rounded-xl border-2 flex flex-col items-center gap-2 ${settings.background === BackgroundType.ORIGINAL ? 'border-brand-500 bg-brand-50' : 'border-gray-100'}`}>
                  <div className="w-8 h-8 rounded-full bg-[url('https://placehold.co/32x32/png')] bg-cover opacity-50"></div>
                  <span className="text-sm font-medium">Ảnh Gốc</span>
                </button>
              </div>
            </div>
          )}

          {/* --- BEAUTY TAB --- */}
          {activeTab === 'beauty' && (
            <div className="space-y-6">
              <div className="bg-gray-50 p-4 rounded-xl space-y-4">
                <h3 className="text-xs font-bold text-gray-500 uppercase">Cơ bản (Không đổi file)</h3>
                <div>
                  <div className="flex justify-between text-xs mb-1"><span>Độ sáng</span><span>{settings.brightness}%</span></div>
                  <input type="range" min="80" max="130" value={settings.brightness} onChange={(e) => onUpdateSettings({...settings, brightness: Number(e.target.value)})} className="w-full h-1.5 bg-gray-300 rounded-lg appearance-none cursor-pointer accent-brand-600" />
                </div>
                <div>
                  <div className="flex justify-between text-xs mb-1"><span>Độ tương phản</span><span>{settings.contrast}%</span></div>
                  <input type="range" min="80" max="130" value={settings.contrast} onChange={(e) => onUpdateSettings({...settings, contrast: Number(e.target.value)})} className="w-full h-1.5 bg-gray-300 rounded-lg appearance-none cursor-pointer accent-brand-600" />
                </div>
              </div>

              <div className="space-y-3">
                <h3 className="text-xs font-bold text-gray-500 uppercase mb-2">Xử lý AI (Thay đổi file)</h3>
                <div>
                   <div className="flex justify-between text-sm font-medium mb-1"><span>Làm mịn da (AI)</span><span className="text-brand-600">{settings.beauty.smoothSkin > 0 ? settings.beauty.smoothSkin : 'Tắt'}</span></div>
                   <input type="range" min="0" max="3" step="1" value={settings.beauty.smoothSkin} onChange={(e) => handleSmoothnessChange(Number(e.target.value))} onMouseUp={handleSliderMouseUp} className="w-full h-1.5 bg-brand-100 rounded-lg appearance-none cursor-pointer accent-brand-600" />
                </div>
                <div className="grid grid-cols-1 gap-2">
                  <label className="flex items-center justify-between p-3 border rounded-lg hover:bg-gray-50"><span className="text-sm font-medium">💡 Cân bằng ánh sáng</span><input type="checkbox" checked={settings.beauty.fixLighting} onChange={() => handleBeautyToggle('fixLighting')} className="w-5 h-5 accent-brand-600" /></label>
                  <label className="flex items-center justify-between p-3 border rounded-lg hover:bg-gray-50"><span className="text-sm font-medium">✨ Xóa mụn/Vết thâm</span><input type="checkbox" checked={settings.beauty.removeBlemishes} onChange={() => handleBeautyToggle('removeBlemishes')} className="w-5 h-5 accent-brand-600" /></label>
                  <label className="flex items-center justify-between p-3 border rounded-lg hover:bg-gray-50"><span className="text-sm font-medium">💄 Makeup nhẹ (Nữ)</span><input type="checkbox" checked={settings.beauty.lightMakeup} onChange={() => handleBeautyToggle('lightMakeup')} className="w-5 h-5 accent-brand-600" /></label>
                   <label className="flex items-center justify-between p-3 border rounded-lg hover:bg-gray-50"><span className="text-sm font-medium">💇 Bù tóc (Đỉnh/Mái)</span><input type="checkbox" checked={settings.beauty.fillHair} onChange={() => handleBeautyToggle('fillHair')} className="w-5 h-5 accent-brand-600" /></label>
                </div>
              </div>
            </div>
          )}

          {/* --- CLOTHING TAB --- */}
          {activeTab === 'clothing' && (
            <div>
              <div className="flex p-1 bg-gray-100 rounded-lg mb-4">
                <button onClick={() => setGenderTab('male')} className={`flex-1 py-1.5 text-sm font-bold rounded-md ${genderTab === 'male' ? 'bg-white text-gray-800 shadow-sm' : 'text-gray-500'}`}>Nam</button>
                <button onClick={() => setGenderTab('female')} className={`flex-1 py-1.5 text-sm font-bold rounded-md ${genderTab === 'female' ? 'bg-white text-gray-800 shadow-sm' : 'text-gray-500'}`}>Nữ</button>
              </div>
              <div className="grid grid-cols-2 gap-3 mb-4">
                <button onClick={() => handleClothingClick('')} className={`p-3 border rounded-lg text-left ${!settings.clothingPrompt ? 'border-green-500 bg-green-50' : 'border-gray-200'}`}>
                   <div className="text-xl mb-1">👕</div><div className="text-xs font-bold">Trang phục gốc</div>
                </button>
                {CLOTHING_CATALOG[genderTab].map((item) => (
                  <button key={item.id} onClick={() => handleClothingClick(item.prompt)} className={`p-3 border rounded-lg text-left hover:shadow-md ${item.color} ${settings.clothingPrompt === item.prompt ? 'bg-gray-50 ring-1 ring-gray-400' : 'bg-white'}`}>
