// --- CLOTHING CATALOG DATA (Vietnamese Context) ---
const CLOTHING_CATALOG = {
  male: [
    { id: 'm_student_scarf', label: 'HS Khăn quàng', color: 'border-red-500', icon: '🧣', prompt: 'wearing a white shirt with a red neckerchief scarf (vietnamese student uniform style)' },
