              {photoTypes.find(t => t.id === selectedSize)?.label}
            </h4>
            <ul className="space-y-4">
              {currentRules.map((rule, idx) => (
                <li key={idx} className="flex gap-3 text-sm text-slate-600 leading-relaxed">
                  <svg className="w-5 h-5 text-green-500 shrink-0 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg>
                  <span>{rule}</span>
                </li>
              ))}
            </ul>
          </div>

          <div className="mt-8">
            <div className="bg-yellow-50 p-4 rounded-xl border border-yellow-100 flex gap-3">
              <svg className="w-6 h-6 text-yellow-600 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"></path></svg>
              <div>
                 <p className="text-xs font-bold text-yellow-800 uppercase mb-1">Lưu ý quan trọng</p>
                 <p className="text-sm text-yellow-700">Vui lòng vén tóc gọn gàng, không để tóc che lông mày hoặc tai. Trang phục có cổ.</p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default StartScreen;

import React, { useState, useEffect, useRef } from 'react';
import { BackgroundType, PhotoSettings, PhotoSize } from '../types';
import { processIDPhoto } from '../services/geminiService';

interface ImageEditorProps {
  originalImage: string;
  settings: PhotoSettings;
  onUpdateSettings: (newSettings: PhotoSettings) => void;
  onProcessedImage: (img: string) => void;
  onNext: () => void;
  onRetake: () => void;
}

const CLOTHING_CATALOG = {
  male: [
    { id: 'm_student_scarf', label: 'HS Khăn quàng', color: 'border-red-500', icon: '🧣', prompt: 'wearing a white shirt with a red neckerchief scarf (vietnamese student uniform style)' },
    { id: 'm_student', label: 'HS Sơ mi trắng', color: 'border-blue-200', icon: '👔', prompt: 'wearing a clean white formal school uniform shirt' },
    { id: 'm_shirt_blue', label: 'Sơ mi Xanh', color: 'border-blue-400', icon: '👔', prompt: 'wearing a light blue formal button-down office shirt' },
    { id: 'm_vest_black', label: 'Vest Đen', color: 'border-gray-800', icon: '🕴️', prompt: 'wearing a formal black business suit with white shirt and tie' },
    { id: 'm_vest_navy', label: 'Vest Navy', color: 'border-blue-900', icon: '🕴️', prompt: 'wearing a formal navy blue business suit with tie' },
    { id: 'm_police', label: 'Sơ mi Công sở', color: 'border-green-700', icon: '👮', prompt: 'wearing a formal beige or green professional uniform shirt' },
  ],
  female: [
    { id: 'f_student_scarf', label: 'HS Khăn quàng', color: 'border-red-500', icon: '🧣', prompt: 'wearing a white shirt with a red neckerchief scarf (vietnamese student uniform style)' },
    { id: 'f_student', label: 'HS Sơ mi trắng', color: 'border-blue-200', icon: '👚', prompt: 'wearing a clean white formal school uniform blouse' },
    { id: 'f_aodai_white', label: 'Áo Dài Trắng', color: 'border-pink-200', icon: '👘', prompt: 'wearing a traditional white Vietnamese Ao Dai with high collar' },
    { id: 'f_aodai_color', label: 'Áo Dài Màu', color: 'border-purple-300', icon: '👘', prompt: 'wearing an elegant colorful traditional Vietnamese Ao Dai' },
    { id: 'f_vest_black', label: 'Vest Đen', color: 'border-gray-800', icon: '💼', prompt: 'wearing a formal black women business blazer and white shirt' },
    { id: 'f_shirt_office', label: 'Sơ mi Nữ', color: 'border-blue-300', icon: '👚', prompt: 'wearing a professional blue office blouse' },
  ]
};

type EditorTab = 'background' | 'beauty' | 'clothing';

const ImageEditor: React.FC<ImageEditorProps> = ({ 
  originalImage, 
  settings, 
  onUpdateSettings,
  onProcessedImage,
  onNext,
  onRetake
}) => {
  const [processedUrl, setProcessedUrl] = useState<string>(originalImage);
  const [isProcessing, setIsProcessing] = useState(false);
  const [activeTab, setActiveTab] = useState<EditorTab>('background');
  const [loadingAction, setLoadingAction] = useState<string>(''); // For granular feedback

  // Before/After Slider State
  const [sliderPosition, setSliderPosition] = useState(50);
  const imageContainerRef = useRef<HTMLDivElement>(null);
  const isDraggingRef = useRef(false);

  // Local state for UI controls before applying AI
  const [clothingInput, setClothingInput] = useState('');
  const [genderTab, setGenderTab] = useState<'male' | 'female'>('male');
  const [apiError, setApiError] = useState('');
  const [securityWarning, setSecurityWarning] = useState('');

  useEffect(() => {
    if (settings.background !== BackgroundType.ORIGINAL && processedUrl === originalImage) {
      triggerAI(settings.background, undefined, undefined, "Đang tách nền tự động...");
    }
  }, []);

  const filterStyle = {
    filter: `brightness(${settings.brightness}%) contrast(${settings.contrast}%)`,
  };

  // --- CORE AI HANDLER ---
  const triggerAI = async (
    overrideBg?: BackgroundType, 
    overrideClothing?: string,
    overrideBeauty?: any,
    actionName: string = "Đang xử lý..."
  ) => {
    setIsProcessing(true);
    setLoadingAction(actionName);
    setApiError('');
    setSecurityWarning('');

    const effBg = overrideBg !== undefined ? overrideBg : settings.background;
    const effClothing = overrideClothing !== undefined ? overrideClothing : settings.clothingPrompt;
    const effBeauty = overrideBeauty !== undefined ? overrideBeauty : settings.beauty;

    try {
      const isDefault = effBg === BackgroundType.ORIGINAL && !effClothing && 
        Object.values(effBeauty).every(v => !v || v === 0);

      if (isDefault) {
        setProcessedUrl(originalImage);
      } else {
        const result = await processIDPhoto(originalImage, effBg, effClothing, effBeauty, settings.size);
        setProcessedUrl(result);
      }

      onUpdateSettings({ 
        ...settings, 
        background: effBg, 
        clothingPrompt: effClothing,
        beauty: effBeauty 
      });
    } catch (err: any) {
      console.error(err);
      setSecurityWarning("Hiệu ứng này không được phép vì ảnh hưởng sinh trắc học khuôn mặt.");
    } finally {
      setIsProcessing(false);
      setLoadingAction('');
    }
  };

  // --- HANDLERS ---
  const handleBgChange = (bg: BackgroundType) => triggerAI(bg, undefined, undefined, "Đang đổi phông nền...");
  const handleClothingClick = (prompt: string) => {
    setClothingInput(prompt);
    triggerAI(undefined, prompt, undefined, prompt ? "Đang thay trang phục..." : "Đang khôi phục áo gốc...");
  };
  const handleBeautyToggle = (key: keyof typeof settings.beauty) => {
    const newBeauty = { ...settings.beauty, [key]: !settings.beauty[key as keyof typeof settings.beauty] };
    triggerAI(undefined, undefined, newBeauty, "Đang áp dụng làm đẹp...");
  };
  const handleSmoothnessChange = (val: number) => {
    onUpdateSettings({ ...settings, beauty: { ...settings.beauty, smoothSkin: val } });
  };
  const handleSliderMouseUp = () => {
     triggerAI(undefined, undefined, undefined, "Đang làm mịn da...");
  };

  const handleMouseMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isDraggingRef.current || !imageContainerRef.current) return;
    const rect = imageContainerRef.current.getBoundingClientRect();
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const x = Math.max(0, Math.min(clientX - rect.left, rect.width));
    setSliderPosition((x / rect.width) * 100);
  };

  const handleFinish = () => {
    const canvas = document.createElement('canvas');
    const img = new Image();
    img.src = processedUrl;
    img.crossOrigin = "anonymous";
    img.onload = () => {
      canvas.width = img.width;
      canvas.height = img.height;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.filter = `brightness(${settings.brightness}%) contrast(${settings.contrast}%)`;
        ctx.drawImage(img, 0, 0);
        onProcessedImage(canvas.toDataURL('image/jpeg', 0.95));
        onNext();
      }
    };
  };

  return (
    <div className="flex flex-col md:flex-row h-full w-full bg-slate-100 overflow-hidden font-sans"
      onMouseMove={handleMouseMove}
      onTouchMove={handleMouseMove}
      onMouseUp={() => { isDraggingRef.current = false; }}
      onTouchEnd={() => { isDraggingRef.current = false; }}
    >

      {/* LEFT: Sidebar / Controls */}
      <div className="w-full md:w-[420px] bg-white shadow-2xl z-20 flex flex-col h-full border-r border-gray-200">

        {/* Header */}
        <div className="p-5 border-b border-gray-100 bg-white flex justify-between items-center">
          <h2 className="text-xl font-extrabold text-gray-800 flex items-center gap-2">
            <span className="text-brand-600 text-2xl">✨</span> Chỉnh sửa
          </h2>
          <div className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">AI Powered</div>
        </div>

        {/* SEGMENTED CONTROL TABS */}
        <div className="px-5 pt-4 pb-2">
          <div className="flex bg-gray-100 p-1 rounded-xl">
            {(['background', 'beauty', 'clothing'] as EditorTab[]).map((tab) => (
               <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                className={`flex-1 py-2 text-xs font-bold uppercase tracking-wide rounded-lg transition-all duration-200 ${
                  activeTab === tab 
                    ? 'bg-white text-brand-600 shadow-sm' 
                    : 'text-gray-500 hover:text-gray-700'
                }`}
              >
                {tab === 'background' ? 'Phông nền' : tab === 'beauty' ? 'Làm đẹp' : 'Trang phục'}
              </button>
            ))}
          </div>
        </div>

        {/* SCROLLABLE CONTENT */}
        <div className="flex-1 overflow-y-auto p-5 bg-white scrollbar-hide">

          {/* --- BACKGROUND TAB --- */}
          {activeTab === 'background' && (
            <div className="space-y-6 animate-fadeIn">
              <div className="grid grid-cols-2 gap-3">
                {[
                  { type: BackgroundType.WHITE, label: 'Trắng (Visa/ID)', color: 'bg-white border-gray-200' },
                  { type: BackgroundType.BLUE, label: 'Xanh (Hồ sơ)', color: 'bg-[#0057B7]' },
                  { type: BackgroundType.GRAY, label: 'Xám (CV)', color: 'bg-gray-300' },
                  { type: BackgroundType.ORIGINAL, label: 'Ảnh Gốc', color: "bg-[url('https://placehold.co/32x32/png')] bg-cover opacity-50" }
                ].map((bg) => (
                  <button 
                    key={bg.type}
                    onClick={() => handleBgChange(bg.type)} 
                    disabled={isProcessing}
                    className={`relative p-4 rounded-2xl border-2 flex flex-col items-center gap-2 transition-all group ${
                      settings.background === bg.type 
                        ? 'border-brand-500 bg-brand-50 shadow-md ring-1 ring-brand-200' 
                        : 'border-slate-100 hover:border-brand-200 hover:bg-slate-50'
                    }`}
                  >
                    <div className={`w-10 h-10 rounded-full shadow-inner ${bg.color} ${settings.background === bg.type ? 'ring-2 ring-offset-2 ring-brand-400' : ''}`}></div>
                    <span className={`text-xs font-bold ${settings.background === bg.type ? 'text-brand-700' : 'text-gray-600'}`}>{bg.label}</span>

                    {/* Active Checkmark */}
                    {settings.background === bg.type && (
                      <div className="absolute top-2 right-2 text-brand-500">
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
                      </div>
                    )}
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* --- BEAUTY TAB --- */}
          {activeTab === 'beauty' && (
            <div className="space-y-6 animate-fadeIn">
              <div className="bg-slate-50 p-5 rounded-2xl space-y-5 border border-slate-100">
                <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider flex items-center gap-2">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4m6 6v10m6-2a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4"></path></svg>
                  Bộ lọc màu (Nhanh)
                </h3>
                <div className="space-y-4">
                  <div className="group">
                    <div className="flex justify-between text-xs font-bold text-gray-700 mb-2">
                      <span>Độ sáng</span>
                      <span className="bg-white px-2 py-0.5 rounded shadow-sm border">{settings.brightness}%</span>
                    </div>
                    <input type="range" min="80" max="130" value={settings.brightness} onChange={(e) => onUpdateSettings({...settings, brightness: Number(e.target.value)})} className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-brand-600 group-hover:accent-brand-500" />
                  </div>
                  <div className="group">
                    <div className="flex justify-between text-xs font-bold text-gray-700 mb-2">
                      <span>Độ tương phản</span>
                      <span className="bg-white px-2 py-0.5 rounded shadow-sm border">{settings.contrast}%</span>
                    </div>
                    <input type="range" min="80" max="130" value={settings.contrast} onChange={(e) => onUpdateSettings({...settings, contrast: Number(e.target.value)})} className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-brand-600 group-hover:accent-brand-500" />
                  </div>
                </div>
              </div>

              <div className="space-y-3">
                <h3 className="text-xs font-bold text-brand-600 uppercase tracking-wider mb-2 flex items-center gap-2">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19.428 15.428a2 2 0 00-1.022-.547l-2.387-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z"></path></svg>
                  AI Retouch (Xử lý sâu)
                </h3>

                <div className="p-4 border border-brand-100 bg-brand-50/50 rounded-xl mb-4">
                   <div className="flex justify-between text-sm font-bold text-brand-800 mb-2">
                     <span>Làm mịn da</span>
                     <span>{settings.beauty.smoothSkin > 0 ? `Level ${settings.beauty.smoothSkin}` : 'Off'}</span>
                   </div>
                   <input type="range" min="0" max="3" step="1" value={settings.beauty.smoothSkin} onChange={(e) => handleSmoothnessChange(Number(e.target.value))} onMouseUp={handleSliderMouseUp} className="w-full h-2 bg-brand-200 rounded-lg appearance-none cursor-pointer accent-brand-600" />
                </div>

                <div className="grid grid-cols-1 gap-2">
                  {[
                    { id: 'fixLighting', label: 'Cân bằng ánh sáng 3D', icon: '💡' },
                    { id: 'removeBlemishes', label: 'Xóa mụn & Vết thâm', icon: '✨' },
                    { id: 'lightMakeup', label: 'Trang điểm nhẹ (Nữ)', icon: '💄' },
                    { id: 'fillHair', label: 'Bù tóc & Tóc con', icon: '💇' }
                  ].map((opt) => (
                     <label key={opt.id} className={`flex items-center justify-between p-3 border rounded-xl cursor-pointer transition-all ${
                       settings.beauty[opt.id as keyof typeof settings.beauty] 
                       ? 'bg-blue-50 border-blue-200 shadow-sm' 
                       : 'hover:bg-gray-50 border-gray-100'
                     }`}>
                      <div className="flex items-center gap-3">
                        <span className="text-lg">{opt.icon}</span>
                        <span className={`text-sm font-medium ${settings.beauty[opt.id as keyof typeof settings.beauty] ? 'text-blue-800' : 'text-gray-700'}`}>{opt.label}</span>
                      </div>
                      <div className={`w-5 h-5 rounded border flex items-center justify-center transition-colors ${settings.beauty[opt.id as keyof typeof settings.beauty] ? 'bg-blue-500 border-blue-500' : 'bg-white border-gray-300'}`}>
                         {settings.beauty[opt.id as keyof typeof settings.beauty] && <svg className="w-3.5 h-3.5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>}
                      </div>
                      <input type="checkbox" checked={!!settings.beauty[opt.id as keyof typeof settings.beauty]} onChange={() => handleBeautyToggle(opt.id as keyof typeof settings.beauty)} className="hidden" />
                    </label>
                  ))}
                </div>
              </div>
            </div>
          )}

          {/* --- CLOTHING TAB --- */}
          {activeTab === 'clothing' && (
            <div className="animate-fadeIn">
              <div className="flex p-1 bg-gray-100 rounded-xl mb-4">
                <button onClick={() => setGenderTab('male')} className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all ${genderTab === 'male' ? 'bg-white text-gray-800 shadow-sm' : 'text-gray-500'}`}>Nam</button>
                <button onClick={() => setGenderTab('female')} className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all ${genderTab === 'female' ? 'bg-white text-gray-800 shadow-sm' : 'text-gray-500'}`}>Nữ</button>
              </div>
              <div className="grid grid-cols-2 gap-3 mb-4">
                <button onClick={() => handleClothingClick('')} className={`p-3 border-2 rounded-xl text-left transition-all ${!settings.clothingPrompt ? 'border-green-500 bg-green-50 shadow-md' : 'border-gray-100 hover:border-gray-300'}`}>
                   <div className="text-2xl mb-2">👕</div>
                   <div className="text-xs font-bold text-gray-800">Trang phục gốc</div>
                   {!settings.clothingPrompt && <div className="text-[10px] text-green-600 font-medium">Đang chọn</div>}
                </button>
                {CLOTHING_CATALOG[genderTab].map((item) => (
                  <button 
                    key={item.id} 
                    onClick={() => handleClothingClick(item.prompt)} 
                    disabled={isProcessing}
                    className={`p-3 border-2 rounded-xl text-left transition-all group relative ${
                      settings.clothingPrompt === item.prompt 
                        ? `bg-white ${item.color} shadow-md` 
                        : 'bg-white border-gray-100 hover:border-gray-300'
                    }`}
                  >
                    <div className="text-2xl mb-2">{item.icon}</div>
                    <div className="text-xs font-bold text-gray-700">{item.label}</div>

                    {/* Active Indicator */}
                    {settings.clothingPrompt === item.prompt && (
                      <div className={`absolute top-2 right-2 w-2 h-2 rounded-full ${item.color.replace('border', 'bg')}`}></div>
                    )}
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* CRITICAL SECURITY WARNING */}
          {securityWarning && (
            <div className="mt-4 p-4 bg-red-50 text-red-700 text-sm font-bold rounded-xl border border-red-200 flex items-start gap-3 animate-pulse shadow-sm">
               <svg className="w-6 h-6 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"></path></svg>
               {securityWarning}
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="p-5 border-t border-gray-200 bg-white space-y-3 z-30">
           <button 
            onClick={handleFinish} 
            disabled={isProcessing} 
            className={`w-full py-4 rounded-xl font-bold shadow-lg flex items-center justify-center gap-2 transition-all transform active:scale-95 ${
              isProcessing 
                ? 'bg-gray-100 text-gray-400 cursor-wait' 
                : 'bg-brand-600 hover:bg-brand-700 text-white hover:shadow-xl'
            }`}
          >
            {isProcessing ? 'Đang chờ xử lý...' : 'Hoàn tất & In Ảnh'}
            {!isProcessing && <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 8l4 4m0 0l-4 4m4-4H3"></path></svg>}
          </button>

          <button 
            onClick={onRetake} 
            disabled={isProcessing}
            className="w-full py-3 bg-white border border-slate-200 text-slate-600 rounded-xl font-bold hover:bg-slate-50 hover:text-red-500 transition"
          >
            Chụp lại
          </button>
        </div>
      </div>

      {/* RIGHT: Preview Area with BEFORE/AFTER SLIDER */}
      <div className="flex-1 bg-slate-100 relative flex flex-col items-center justify-center p-6">

        {/* Helper Banner */}
        <div className="absolute top-6 z-10 bg-white/90 backdrop-blur text-slate-600 px-5 py-2.5 rounded-full text-xs font-bold border border-white shadow-sm flex items-center gap-2 select-none">
          <svg className="w-4 h-4 text-brand-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7h12m0 0l-4-4m4 4l-4 4m0 6H4m0 0l4 4m-4-4l4-4"></path></svg>
          Kéo thanh trượt để so sánh Trước / Sau
        </div>

        {/* Image Container with Slider */}
        <div 
          ref={imageContainerRef}
          className="relative shadow-[0_20px_50px_-12px_rgba(0,0,0,0.25)] bg-white select-none cursor-ew-resize overflow-hidden rounded-sm ring-4 ring-white" 
          style={{ 
             maxHeight: '85vh', 
             aspectRatio: settings.size === PhotoSize.SIZE_5X5 ? '1/1' : '2/3',
             height: '85vh' 
          }}
          onMouseDown={() => { isDraggingRef.current = true; }}
          onTouchStart={() => { isDraggingRef.current = true; }}
        >
          {/* PROCESSING OVERLAY */}
          {isProcessing && (
            <div className="absolute inset-0 z-30 bg-black/40 flex flex-col items-center justify-center backdrop-blur-[2px]">
               <div className="bg-white p-6 rounded-2xl shadow-2xl flex flex-col items-center animate-bounce-in">
                 <div className="w-12 h-12 border-4 border-brand-200 border-t-brand-600 rounded-full animate-spin mb-3"></div>
                 <p className="text-brand-800 font-bold text-sm">{loadingAction}</p>
                 <p className="text-[10px] text-gray-400 mt-1">Giữ nguyên sinh trắc học...</p>
               </div>
            </div>
          )}

          {/* BACKGROUND IMAGE (AFTER) */}
          <img 
            src={processedUrl} 
            alt="After" 
            className="absolute inset-0 w-full h-full object-contain pointer-events-none bg-white"
            style={filterStyle} 
          />

          {/* FOREGROUND IMAGE (BEFORE) - Clipped */}
          <div 
            className="absolute inset-0 w-full h-full overflow-hidden border-r-2 border-white pointer-events-none bg-white"
            style={{ width: `${sliderPosition}%` }}
          >
             <img 
              src={originalImage} 
              alt="Before" 
