                      <div className={`w-5 h-5 rounded border flex items-center justify-center transition-colors ${settings.beauty[opt.id as keyof typeof settings.beauty] ? 'bg-blue-500 border-blue-500' : 'bg-white border-gray-300'}`}>
                         {settings.beauty[opt.id as keyof typeof settings.beauty] && <svg className="w-3.5 h-3.5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>}
